import org.apache.pdfbox.Loader;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;
import org.apache.pdfbox.text.PDFTextStripper;

import java.awt.geom.Point2D;
import java.io.File;
import java.util.*;

/**
 * Classifies statement fixtures into layout families:
 * - counts text chars (electronic vs scanned)
 * - collects horizontal/vertical ruling segments (stroked + thin filled rects)
 */
public class CorpusAnalyzer {

    static class Seg {
        double x1, y1, x2, y2;
        Seg(double x1, double y1, double x2, double y2) { this.x1 = x1; this.y1 = y1; this.x2 = x2; this.y2 = y2; }
        boolean horizontal() { return Math.abs(y2 - y1) < 1.5 && Math.abs(x2 - x1) > 5; }
        boolean vertical() { return Math.abs(x2 - x1) < 1.5 && Math.abs(y2 - y1) > 5; }
        double hLen() { return Math.abs(x2 - x1); }
        double vLen() { return Math.abs(y2 - y1); }
    }

    static class RulingCollector extends PDFGraphicsStreamEngine {
        List<Seg> segs = new ArrayList<>();
        List<Point2D> path = new ArrayList<>();
        Point2D current;
        int images = 0;

        protected RulingCollector(PDPage page) { super(page); }

        void addSeg(Point2D a, Point2D b) {
            segs.add(new Seg(a.getX(), a.getY(), b.getX(), b.getY()));
        }

        @Override public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) {
            // rectangle -> 4 segments
            addSeg(p0, p1); addSeg(p1, p2); addSeg(p2, p3); addSeg(p3, p0);
        }
        @Override public void drawImage(PDImage pdImage) { images++; }
        @Override public void clip(int windingRule) {}
        @Override public void moveTo(float x, float y) { current = new Point2D.Float(x, y); }
        @Override public void lineTo(float x, float y) {
            Point2D p = new Point2D.Float(x, y);
            if (current != null) addSeg(current, p);
            current = p;
        }
        @Override public void curveTo(float x1, float y1, float x2, float y2, float x3, float y3) { current = new Point2D.Float(x3, y3); }
        @Override public Point2D getCurrentPoint() { return current == null ? new Point2D.Float(0, 0) : current; }
        @Override public void closePath() {}
        @Override public void endPath() {}
        @Override public void strokePath() {}
        @Override public void fillPath(int windingRule) {}
        @Override public void fillAndStrokePath(int windingRule) {}
        @Override public void shadingFill(COSName shadingName) {}
    }

    static Set<Double> cluster(List<Double> vals, double tol) {
        Collections.sort(vals);
        Set<Double> out = new TreeSet<>();
        Double last = null;
        for (double v : vals) {
            if (last == null || v - last > tol) { out.add(v); last = v; }
        }
        return out;
    }

    public static void main(String[] args) throws Exception {
        File root = new File(args[0]);
        File[] banks = root.listFiles(File::isDirectory);
        Arrays.sort(banks);
        for (File bank : banks) {
            File[] pdfs = bank.listFiles((d, n) -> n.toLowerCase().endsWith(".pdf"));
            Arrays.sort(pdfs);
            for (File pdf : pdfs) {
                try (PDDocument doc = Loader.loadPDF(pdf)) {
                    int pageNo = Math.min(2, doc.getNumberOfPages()); // analyze a transaction-y page
                    PDPage page = doc.getPage(pageNo - 1);
                    PDFTextStripper ts = new PDFTextStripper();
                    ts.setStartPage(pageNo); ts.setEndPage(pageNo);
                    String text = ts.getText(doc);
                    RulingCollector rc = new RulingCollector(page);
                    rc.processPage(page);
                    List<Double> hy = new ArrayList<>(), vx = new ArrayList<>();
                    double maxHLen = 0, maxVLen = 0;
                    int hCount = 0, vCount = 0;
                    for (Seg s : rc.segs) {
                        if (s.horizontal() && s.hLen() > 100) { hy.add(Math.min(s.y1, s.y2)); hCount++; maxHLen = Math.max(maxHLen, s.hLen()); }
                        if (s.vertical() && s.vLen() > 20) { vx.add(Math.min(s.x1, s.x2)); vCount++; maxVLen = Math.max(maxVLen, s.vLen()); }
                    }
                    Set<Double> hLines = cluster(hy, 2.0);
                    Set<Double> vLines = cluster(vx, 2.0);
                    String cls;
                    boolean hasText = text.trim().length() > 100;
                    if (!hasText) cls = "SCANNED";
                    else if (hLines.size() >= 6 && vLines.size() >= 4) cls = "BORDERED_GRID";
                    else if (vLines.size() >= 4) cls = "BOX_GUIDED";
                    else cls = "TEXT_ALIGNED";
                    System.out.printf("%-28s %-14s pages=%-3d pg=%d chars=%-6d hRul=%-3d vRul=%-3d img=%-2d -> %s%n",
                            bank.getName(), pdf.getName(), doc.getNumberOfPages(), pageNo, text.trim().length(),
                            hLines.size(), vLines.size(), rc.images, cls);
                } catch (Exception e) {
                    System.out.printf("%-28s %-14s ERROR %s%n", bank.getName(), pdf.getName(), e.getMessage());
                }
            }
        }
    }
}

