package com.finboost.bank.statement.parser.representation.document.extraction;

/**
 * Indicates which extraction engine produced the transaction tables of a
 * statement (or of the statements backing an account).
 *
 * <ul>
 *     <li>{@link #NATIVE} - the offline, in-process (PDFBox based) table extraction path.</li>
 *     <li>{@link #ML} - the remote ML document-intelligence extraction path.</li>
 *     <li>{@link #NATIVE_FALLBACK_ML} - the native path was attempted for a supported
 *     bank-format family but did not succeed, so the remote ML path was used instead.</li>
 * </ul>
 */
public enum ExtractionMode {
    NATIVE,
    ML,
    NATIVE_FALLBACK_ML;

    /**
     * Aggregates statement level modes to an account level mode.
     * All statements native -> NATIVE, any native-to-ML fallback -> NATIVE_FALLBACK_ML,
     * otherwise -> ML.
     */
    public static ExtractionMode aggregate(Iterable<ExtractionMode> modes) {
        boolean any = false;
        boolean allNative = true;
        boolean anyFallback = false;
        for (ExtractionMode mode : modes) {
            if (mode == null) {
                continue;
            }
            any = true;
            if (mode != NATIVE) {
                allNative = false;
            }
            if (mode == NATIVE_FALLBACK_ML) {
                anyFallback = true;
            }
        }
        if (!any) {
            return null;
        }
        if (allNative) {
            return NATIVE;
        }
        return anyFallback ? NATIVE_FALLBACK_ML : ML;
    }
}

