package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

/**
 * The native (offline, in-process) table extraction layout families supported for
 * bank statement PDFs.
 */
public enum NativeLayoutPolicy {

    /**
     * Tables drawn as a full grid: every row and column is separated by ruled lines
     * (possibly dashed). Cells are recovered from the intersections of the rulings.
     */
    BORDERED_GRID,

    /**
     * Tables guided by vertical box/column separators only: columns are ruled but the
     * individual transaction rows are not. Rows are recovered from text lines anchored
     * on the transaction-date column.
     */
    BOX_GUIDED,

    /**
     * No usable rulings at all: columns are recovered from the alignment of the header
     * labels and the data below them, rows are selected by date-anchored text lines.
     */
    TEXT_ALIGNED_ROW_SELECTED
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import lombok.AllArgsConstructor;
import lombok.Data;

/**
 * An axis-aligned ruling line segment extracted from a PDF page.
 * Coordinates are in inches, relative to the top-left corner of the page.
 */
@Data
@AllArgsConstructor
public class NativeRuling {

    private float x1;
    private float y1;
    private float x2;
    private float y2;

    /** Maximum deviation (inches) from the axis for a segment to count as axis aligned. */
    public static final float AXIS_TOLERANCE = 0.03f;

    public static NativeRuling normalized(float x1, float y1, float x2, float y2) {
        return new NativeRuling(Math.min(x1, x2), Math.min(y1, y2), Math.max(x1, x2), Math.max(y1, y2));
    }

    public boolean isHorizontal() {
        return (y2 - y1) <= AXIS_TOLERANCE && (x2 - x1) > (y2 - y1);
    }

    public boolean isVertical() {
        return (x2 - x1) <= AXIS_TOLERANCE && (y2 - y1) > (x2 - x1);
    }

    public float length() {
        return isHorizontal() ? x2 - x1 : y2 - y1;
    }

    /** The coordinate perpendicular to the ruling direction (y for horizontal, x for vertical). */
    public float position() {
        return isHorizontal() ? (y1 + y2) / 2f : (x1 + x2) / 2f;
    }

    /** Start of the ruling along its direction. */
    public float start() {
        return isHorizontal() ? x1 : y1;
    }

    /** End of the ruling along its direction. */
    public float end() {
        return isHorizontal() ? x2 : y2;
    }

    /** Overlap length with another ruling of the same orientation, along the ruling direction. */
    public float overlap(NativeRuling other) {
        float start = Math.max(start(), other.start());
        float end = Math.min(end(), other.end());
        return Math.max(0f, end - start);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.List;

/**
 * The native (PDFBox extracted) content of a single PDF page: word boxes, ruling
 * lines and the plain page text. All coordinates are in inches with the origin at
 * the top-left corner of the page (the same coordinate convention used by the ML
 * document extraction path).
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class NativePdfPageContent {
    private int pageNumber;
    private float width;
    private float height;
    private List<Word> words;
    private List<NativeRuling> horizontalRulings;
    private List<NativeRuling> verticalRulings;
    private String text;
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;
import org.apache.pdfbox.text.PDFTextStripper;
import org.apache.pdfbox.text.TextPosition;
import org.springframework.stereotype.Service;

import java.awt.geom.Point2D;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Reads the native content (word boxes, ruling lines and text) of an electronic PDF
 * using PDFBox only, i.e. fully offline. Coordinates are converted to inches with a
 * top-left origin so the produced {@link Word} objects follow the same convention as
 * the ML document extraction path.
 */
@Service
@Slf4j
public class NativePdfContentReader {

    private static final float POINTS_PER_INCH = 72.0f;
    /** Rulings closer than this (inches) on the perpendicular axis are considered the same line. */
    private static final float RULING_POSITION_TOLERANCE = 0.035f;
    /** Collinear rulings with a gap up to this (inches) are merged (handles dashed rulings). */
    private static final float RULING_GAP_TOLERANCE = 0.18f;
    /** Filled rectangles thinner than this (points) are treated as drawn lines. */
    private static final float FILLED_LINE_MAX_THICKNESS_POINTS = 5.0f;

    /**
     * Extracts the native page content for every page of the given PDF.
     *
     * @return one {@link NativePdfPageContent} per page, or an empty list when the file
     * cannot be read as an electronic PDF.
     */
    public List<NativePdfPageContent> readPages(File pdfFile) throws IOException {
        List<NativePdfPageContent> pages = new LinkedList<>();
        try (PDDocument document = Loader.loadPDF(pdfFile)) {
            int pageCount = document.getNumberOfPages();
            for (int pageIndex = 0; pageIndex < pageCount; pageIndex++) {
                pages.add(readPage(document, pageIndex));
            }
        }
        return pages;
    }

    private NativePdfPageContent readPage(PDDocument document, int pageIndex) throws IOException {
        int pageNumber = pageIndex + 1;
        PDPage page = document.getPage(pageIndex);
        PDRectangle cropBox = page.getCropBox();

        NativePdfPageContent content = new NativePdfPageContent();
        content.setPageNumber(pageNumber);
        content.setWidth(cropBox.getWidth() / POINTS_PER_INCH);
        content.setHeight(cropBox.getHeight() / POINTS_PER_INCH);

        // Words + page text
        WordStripper stripper = new WordStripper(pageNumber);
        stripper.setStartPage(pageNumber);
        stripper.setEndPage(pageNumber);
        String text = stripper.getText(document);
        content.setText(text != null ? text : "");
        List<Word> words = stripper.getWords();
        words.sort(Comparator.comparing(Word::getY1).thenComparing(Word::getX1));
        int wordIndex = 1;
        for (Word word : words) {
            word.setPageIndex(pageNumber);
            word.setWordIndex(wordIndex++);
        }
        content.setWords(words);

        // Rulings (only meaningful for unrotated pages)
        List<NativeRuling> horizontal = new LinkedList<>();
        List<NativeRuling> vertical = new LinkedList<>();
        if (page.getRotation() == 0) {
            try {
                RulingCollector collector = new RulingCollector(page, cropBox);
                collector.processPage(page);
                horizontal = mergeRulings(collector.getHorizontalRulings(), true);
                vertical = mergeRulings(collector.getVerticalRulings(), false);
            } catch (Exception e) {
                log.warn("Failed to collect rulings from page {}: {}", pageNumber, e.getMessage());
            }
        }
        content.setHorizontalRulings(horizontal);
        content.setVerticalRulings(vertical);
        return content;
    }

    /**
     * Merges collinear ruling fragments (e.g. dashed lines) into single rulings.
     */
    private List<NativeRuling> mergeRulings(List<NativeRuling> rulings, boolean horizontal) {
        List<NativeRuling> sorted = new ArrayList<>(rulings);
        sorted.sort(Comparator.comparing(NativeRuling::position).thenComparing(NativeRuling::start));

        List<List<NativeRuling>> positionGroups = new ArrayList<>();
        List<NativeRuling> currentGroup = null;
        float currentPosition = Float.NaN;
        for (NativeRuling ruling : sorted) {
            if (currentGroup == null || ruling.position() - currentPosition > RULING_POSITION_TOLERANCE) {
                currentGroup = new ArrayList<>();
                positionGroups.add(currentGroup);
            }
            currentGroup.add(ruling);
            currentPosition = ruling.position();
        }

        List<NativeRuling> merged = new LinkedList<>();
        for (List<NativeRuling> group : positionGroups) {
            group.sort(Comparator.comparing(NativeRuling::start));
            float position = group.get(0).position();
            float start = group.get(0).start();
            float end = group.get(0).end();
            for (NativeRuling ruling : group) {
                if (ruling.start() - end > RULING_GAP_TOLERANCE) {
                    merged.add(createRuling(horizontal, position, start, end));
                    start = ruling.start();
                }
                end = Math.max(end, ruling.end());
            }
            merged.add(createRuling(horizontal, position, start, end));
        }
        return merged;
    }

    private NativeRuling createRuling(boolean horizontal, float position, float start, float end) {
        return horizontal
                ? new NativeRuling(start, position, end, position)
                : new NativeRuling(position, start, position, end);
    }

    /**
     * PDF text stripper that keeps the word boxes it encounters. PDFBox calls
     * {@link #writeString(String, List)} once per positional word when
     * sort-by-position is enabled.
     */
    private static class WordStripper extends PDFTextStripper {
        private final int pageNumber;
        private final List<Word> words = new LinkedList<>();

        WordStripper(int pageNumber) throws IOException {
            this.pageNumber = pageNumber;
            setSortByPosition(true);
        }

        List<Word> getWords() {
            return words;
        }

        @Override
        protected void writeString(String text, List<TextPosition> textPositions) throws IOException {
            super.writeString(text, textPositions);
            if (textPositions == null || textPositions.isEmpty()) {
                return;
            }
            List<TextPosition> currentWord = new ArrayList<>();
            for (TextPosition position : textPositions) {
                String unicode = position.getUnicode();
                if (unicode == null || unicode.isBlank()) {
                    addWord(currentWord);
                    currentWord = new ArrayList<>();
                } else {
                    currentWord.add(position);
                }
            }
            addWord(currentWord);
        }

        private void addWord(List<TextPosition> positions) {
            if (positions.isEmpty()) {
                return;
            }
            StringBuilder wordText = new StringBuilder();
            float minX = Float.MAX_VALUE;
            float maxX = -Float.MAX_VALUE;
            float baseline = -Float.MAX_VALUE;
            float maxHeight = 0f;
            for (TextPosition position : positions) {
                wordText.append(position.getUnicode());
                minX = Math.min(minX, position.getXDirAdj());
                maxX = Math.max(maxX, position.getXDirAdj() + position.getWidthDirAdj());
                baseline = Math.max(baseline, position.getYDirAdj());
                maxHeight = Math.max(maxHeight, Math.abs(position.getHeightDir()));
            }
            if (maxHeight <= 0f) {
                maxHeight = 6f; // sensible default in points
            }
            float left = minX / POINTS_PER_INCH;
            float right = maxX / POINTS_PER_INCH;
            float bottom = baseline / POINTS_PER_INCH;
            float top = bottom - (maxHeight / POINTS_PER_INCH);
            words.add(new Word(wordText.toString(),
                    left, top,
                    right, top,
                    right, bottom,
                    left, bottom,
                    pageNumber,
                    right - left,
                    bottom - top,
                    pageNumber,
                    0));
        }
    }

    /**
     * Collects axis-aligned ruling lines from the page's vector graphics. Segments are
     * committed when they are actually painted (stroked, or filled as thin rectangles),
     * so clipping-only paths are ignored.
     */
    private static class RulingCollector extends PDFGraphicsStreamEngine {

        private final PDRectangle cropBox;
        private final List<NativeRuling> horizontalRulings = new LinkedList<>();
        private final List<NativeRuling> verticalRulings = new LinkedList<>();

        private final List<float[]> pendingSegments = new ArrayList<>();
        private final List<float[]> pendingRectangles = new ArrayList<>();
        private Point2D currentPoint;
        private Point2D subPathStart;

        protected RulingCollector(PDPage page, PDRectangle cropBox) {
            super(page);
            this.cropBox = cropBox;
        }

        List<NativeRuling> getHorizontalRulings() {
            return horizontalRulings;
        }

        List<NativeRuling> getVerticalRulings() {
            return verticalRulings;
        }

        @Override
        public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) {
            float minX = (float) Math.min(Math.min(p0.getX(), p1.getX()), Math.min(p2.getX(), p3.getX()));
            float maxX = (float) Math.max(Math.max(p0.getX(), p1.getX()), Math.max(p2.getX(), p3.getX()));
            float minY = (float) Math.min(Math.min(p0.getY(), p1.getY()), Math.min(p2.getY(), p3.getY()));
            float maxY = (float) Math.max(Math.max(p0.getY(), p1.getY()), Math.max(p2.getY(), p3.getY()));
            pendingRectangles.add(new float[]{minX, minY, maxX, maxY});
            // Rectangle edges as stroked candidates
            pendingSegments.add(new float[]{minX, minY, maxX, minY});
            pendingSegments.add(new float[]{maxX, minY, maxX, maxY});
            pendingSegments.add(new float[]{maxX, maxY, minX, maxY});
            pendingSegments.add(new float[]{minX, maxY, minX, minY});
            currentPoint = p0;
        }

        @Override
        public void drawImage(PDImage pdImage) {
        }

        @Override
        public void clip(int windingRule) {
        }

        @Override
        public void moveTo(float x, float y) {
            currentPoint = new Point2D.Float(x, y);
            subPathStart = currentPoint;
        }

        @Override
        public void lineTo(float x, float y) {
            Point2D next = new Point2D.Float(x, y);
            if (currentPoint != null) {
                pendingSegments.add(new float[]{(float) currentPoint.getX(), (float) currentPoint.getY(), x, y});
            }
            currentPoint = next;
        }

        @Override
        public void curveTo(float x1, float y1, float x2, float y2, float x3, float y3) {
            currentPoint = new Point2D.Float(x3, y3);
        }

        @Override
        public Point2D getCurrentPoint() {
            return currentPoint != null ? currentPoint : new Point2D.Float(0, 0);
        }

        @Override
        public void closePath() {
            if (currentPoint != null && subPathStart != null && !currentPoint.equals(subPathStart)) {
                pendingSegments.add(new float[]{(float) currentPoint.getX(), (float) currentPoint.getY(),
                        (float) subPathStart.getX(), (float) subPathStart.getY()});
            }
            currentPoint = subPathStart;
        }

        @Override
        public void endPath() {
            clearPending();
        }

        @Override
        public void strokePath() {
            for (float[] segment : pendingSegments) {
                commitSegment(segment[0], segment[1], segment[2], segment[3]);
            }
            clearPending();
        }

        @Override
        public void fillPath(int windingRule) {
            // Thin filled rectangles are effectively drawn lines
            for (float[] rect : pendingRectangles) {
                float width = rect[2] - rect[0];
                float height = rect[3] - rect[1];
                if (height <= FILLED_LINE_MAX_THICKNESS_POINTS && width > height) {
                    float y = (rect[1] + rect[3]) / 2f;
                    commitSegment(rect[0], y, rect[2], y);
                } else if (width <= FILLED_LINE_MAX_THICKNESS_POINTS && height >= width) {
                    float x = (rect[0] + rect[2]) / 2f;
                    commitSegment(x, rect[1], x, rect[3]);
                }
            }
            clearPending();
        }

        @Override
        public void fillAndStrokePath(int windingRule) {
            for (float[] segment : pendingSegments) {
                commitSegment(segment[0], segment[1], segment[2], segment[3]);
            }
            clearPending();
        }

        @Override
        public void shadingFill(COSName shadingName) {
        }

        private void clearPending() {
            pendingSegments.clear();
            pendingRectangles.clear();
            currentPoint = null;
            subPathStart = null;
        }

        private void commitSegment(float x1, float y1, float x2, float y2) {
            // Convert PDF user space (points, bottom-left origin) to inches, top-left origin
            float ax1 = (x1 - cropBox.getLowerLeftX()) / POINTS_PER_INCH;
            float ax2 = (x2 - cropBox.getLowerLeftX()) / POINTS_PER_INCH;
            float ay1 = (cropBox.getUpperRightY() - y1) / POINTS_PER_INCH;
            float ay2 = (cropBox.getUpperRightY() - y2) / POINTS_PER_INCH;
            NativeRuling ruling = NativeRuling.normalized(ax1, ay1, ax2, ay2);
            if (ruling.length() < 0.01f) {
                return;
            }
            if (ruling.isHorizontal()) {
                horizontalRulings.add(ruling);
            } else if (ruling.isVertical()) {
                verticalRulings.add(ruling);
            }
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.Getter;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

/**
 * A horizontal line of text on a page, built from word boxes that vertically overlap.
 * Coordinates are in inches from the top-left corner of the page.
 */
@Getter
public class NativeTextLine {

    private float top;
    private float bottom;
    private final List<Word> words = new ArrayList<>();

    public NativeTextLine(Word word) {
        this.top = word.getY1();
        this.bottom = word.getY3();
        this.words.add(word);
    }

    public void add(Word word) {
        this.top = Math.min(this.top, word.getY1());
        this.bottom = Math.max(this.bottom, word.getY3());
        this.words.add(word);
    }

    public float centerY() {
        return (top + bottom) / 2f;
    }

    public float height() {
        return bottom - top;
    }

    public boolean overlapsVertically(Word word) {
        float wordCenter = (word.getY1() + word.getY3()) / 2f;
        float lineCenter = centerY();
        return (wordCenter >= top && wordCenter <= bottom)
                || (lineCenter >= word.getY1() && lineCenter <= word.getY3());
    }

    public void sortWords() {
        words.sort(Comparator.comparing(Word::getX1));
    }

    public float minX() {
        return words.stream().map(Word::getX1).min(Comparator.naturalOrder()).orElse(0f);
    }

    public float maxX() {
        return words.stream().map(Word::getX3).max(Comparator.naturalOrder()).orElse(0f);
    }

    public String content() {
        return words.stream().map(Word::getContent).collect(Collectors.joining(" "));
    }

    /**
     * Concatenated content of the words whose horizontal center is inside [left, right].
     */
    public String contentBetween(float left, float right) {
        StringBuilder builder = new StringBuilder();
        for (Word word : words) {
            float centerX = (word.getX1() + word.getX3()) / 2f;
            if (centerX >= left && centerX <= right) {
                if (builder.length() > 0) {
                    builder.append(' ');
                }
                builder.append(word.getContent());
            }
        }
        return builder.toString();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.AllArgsConstructor;
import lombok.Getter;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * Shared helpers for the native table extractors: text-line clustering, header /
 * date / amount token detection, position clustering and table assembly.
 * All coordinates are in inches from the top-left corner of the page.
 */
public final class NativeTableSupport {

    private NativeTableSupport() {
    }

    private static final Pattern NUMERIC_DATE = Pattern.compile("\\b\\d{1,2}[-/.]\\d{1,2}[-/.]\\d{2,4}\\b");
    private static final Pattern ISO_DATE = Pattern.compile("\\b\\d{4}[-/.]\\d{1,2}[-/.]\\d{1,2}\\b");
    private static final Pattern MONTH_NAME_DATE = Pattern.compile(
            "\\b\\d{1,2}[-/., ]{0,2}(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*[-/., ]{0,2}\\d{2,4}\\b",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern AMOUNT = Pattern.compile("\\d[\\d,]*\\.\\d{1,2}");

    private static final String[][] HEADER_KEYWORD_GROUPS = {
            {"date"},
            {"description", "particular", "narration", "remark", "details", "transaction"},
            {"chq", "cheque", "ref", "utr", "instrument"},
            {"debit", "withdrawal", "withdrawl", "dr amount", "dr amt"},
            {"credit", "deposit", "cr amount", "cr amt"},
            {"amount"},
            {"balance"}
    };

    /**
     * Groups the words of a page (or a region) into horizontal text lines.
     */
    public static List<NativeTextLine> buildTextLines(List<Word> words) {
        List<Word> sorted = new ArrayList<>(words);
        sorted.sort(Comparator.comparing(Word::getY1).thenComparing(Word::getX1));

        List<NativeTextLine> lines = new LinkedList<>();
        for (Word word : sorted) {
            NativeTextLine target = null;
            for (NativeTextLine line : lines) {
                if (line.overlapsVertically(word)) {
                    target = line;
                    break;
                }
            }
            if (target == null) {
                lines.add(new NativeTextLine(word));
            } else {
                target.add(word);
            }
        }
        lines.forEach(NativeTextLine::sortWords);
        lines.sort(Comparator.comparing(NativeTextLine::getTop));
        return lines;
    }

    public static boolean containsDate(String content) {
        if (content == null || content.isBlank()) {
            return false;
        }
        return NUMERIC_DATE.matcher(content).find()
                || ISO_DATE.matcher(content).find()
                || MONTH_NAME_DATE.matcher(content).find();
    }

    public static boolean containsAmount(String content) {
        return content != null && AMOUNT.matcher(content).find();
    }

    /**
     * @return the number of distinct transaction-table header keyword groups present
     * in the given content.
     */
    public static int headerKeywordGroupCount(String content) {
        if (content == null || content.isBlank()) {
            return 0;
        }
        String lower = content.toLowerCase(Locale.ROOT);
        int count = 0;
        for (String[] group : HEADER_KEYWORD_GROUPS) {
            for (String keyword : group) {
                if (lower.contains(keyword)) {
                    count++;
                    break;
                }
            }
        }
        return count;
    }

    /**
     * A transaction-table header line mentions at least a date column plus two other
     * known column labels.
     */
    public static boolean isTransactionHeaderLine(String content) {
        if (content == null) {
            return false;
        }
        String lower = content.toLowerCase(Locale.ROOT);
        return lower.contains("date") && headerKeywordGroupCount(content) >= 3;
    }

    /**
     * Clusters one-dimensional positions and returns the cluster centers, sorted.
     */
    public static List<Float> clusterPositions(List<Float> positions, float tolerance) {
        List<Float> sorted = new ArrayList<>(positions);
        sorted.sort(Comparator.naturalOrder());
        List<Float> centers = new ArrayList<>();
        List<Float> cluster = new ArrayList<>();
        Float last = null;
        for (Float position : sorted) {
            if (last != null && position - last > tolerance) {
                centers.add(average(cluster));
                cluster.clear();
            }
            cluster.add(position);
            last = position;
        }
        if (!cluster.isEmpty()) {
            centers.add(average(cluster));
        }
        return centers;
    }

    private static float average(List<Float> values) {
        float sum = 0f;
        for (float value : values) {
            sum += value;
        }
        return sum / values.size();
    }

    /**
     * A logical table row: one or more text lines merged together (multi-line
     * descriptions are part of the anchor row above them).
     */
    @Getter
    public static class LogicalRow {
        private float top;
        private float bottom;
        private final boolean header;
        private final List<Word> words = new ArrayList<>();

        public LogicalRow(float top, float bottom, boolean header) {
            this.top = top;
            this.bottom = bottom;
            this.header = header;
        }

        public static LogicalRow fromLine(NativeTextLine line, boolean header) {
            LogicalRow row = new LogicalRow(line.getTop(), line.getBottom(), header);
            row.words.addAll(line.getWords());
            return row;
        }

        public void addLine(NativeTextLine line) {
            this.top = Math.min(this.top, line.getTop());
            this.bottom = Math.max(this.bottom, line.getBottom());
            this.words.addAll(line.getWords());
        }

        public void addWords(List<Word> newWords) {
            this.words.addAll(newWords);
        }
    }

    /**
     * Groups text lines into logical rows anchored on lines that carry a date-like
     * token within the date column range. Non-anchored lines are treated as
     * continuations of the row above them.
     *
     * @param lines               text lines, sorted top to bottom
     * @param dateColumnLeft      left edge of the transaction-date column
     * @param dateColumnRight     right edge of the transaction-date column
     * @param maxContinuationGap  maximum vertical gap (inches) between a row and a continuation line
     */
    public static List<LogicalRow> groupLinesIntoRows(List<NativeTextLine> lines,
                                                      float dateColumnLeft,
                                                      float dateColumnRight,
                                                      float maxContinuationGap) {
        List<LogicalRow> rows = new LinkedList<>();
        LogicalRow current = null;
        for (NativeTextLine line : lines) {
            boolean anchored = containsDate(line.contentBetween(dateColumnLeft, dateColumnRight));
            if (anchored) {
                current = LogicalRow.fromLine(line, false);
                rows.add(current);
            } else if (current != null && line.getTop() - current.getBottom() <= maxContinuationGap) {
                current.addLine(line);
            }
        }
        return rows;
    }

    /**
     * Determines the column index most likely to hold the transaction date.
     *
     * @return the date column index, or -1 when it cannot be determined
     */
    public static int findDateColumnIndex(List<Float> columnBoundaries,
                                          List<NativeTextLine> headerLines,
                                          List<NativeTextLine> dataLines) {
        int columnCount = columnBoundaries.size() - 1;
        // 1. By header label
        for (int col = 0; col < columnCount; col++) {
            float left = columnBoundaries.get(col);
            float right = columnBoundaries.get(col + 1);
            for (NativeTextLine headerLine : headerLines) {
                String label = headerLine.contentBetween(left, right).toLowerCase(Locale.ROOT);
                if (label.contains("date")) {
                    return col;
                }
            }
        }
        // 2. By data content of the leading columns
        int bestColumn = -1;
        int bestCount = 0;
        for (int col = 0; col < Math.min(3, columnCount); col++) {
            float left = columnBoundaries.get(col);
            float right = columnBoundaries.get(col + 1);
            int count = 0;
            for (NativeTextLine dataLine : dataLines) {
                if (containsDate(dataLine.contentBetween(left, right))) {
                    count++;
                }
            }
            if (count > bestCount) {
                bestCount = count;
                bestColumn = col;
            }
        }
        return bestCount >= 2 ? bestColumn : -1;
    }

    /**
     * Assembles a {@link Table} from column boundaries and logical rows. Cell polygons
     * are derived from the boundaries and each row's vertical extent; words are
     * assigned to cells by the horizontal position of their center.
     */
    public static Table buildTable(int pageNumber, List<Float> columnBoundaries, List<LogicalRow> rows) {
        int columnCount = columnBoundaries.size() - 1;
        float left = columnBoundaries.get(0);
        float right = columnBoundaries.get(columnCount);
        float top = rows.get(0).getTop();
        float bottom = rows.get(rows.size() - 1).getBottom();

        Table table = new Table();
        table.setPageNumber(pageNumber);
        table.setX1(left);
        table.setY1(top);
        table.setX2(right);
        table.setY2(top);
        table.setX3(right);
        table.setY3(bottom);
        table.setX4(left);
        table.setY4(bottom);
        table.setTotalRows(rows.size());
        table.setTotalColumns(columnCount);
        table.setSpanOffset(0);
        table.setSpanLength(0);
        table.setColType(new ArrayList<>());
        table.setTxnColType(new ArrayList<>());
        table.setColumnBoundaries(new ArrayList<>(columnBoundaries));

        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
        for (int rowIndex = 0; rowIndex < rows.size(); rowIndex++) {
            LogicalRow row = rows.get(rowIndex);
            Map<Integer, TableCell> rowCells = new LinkedHashMap<>();
            List<List<Word>> wordsPerColumn = new ArrayList<>();
            for (int col = 0; col < columnCount; col++) {
                wordsPerColumn.add(new LinkedList<>());
            }
            for (Word word : row.getWords()) {
                float centerX = (word.getX1() + word.getX3()) / 2f;
                int col = columnIndexFor(columnBoundaries, centerX);
                wordsPerColumn.get(col).add(word);
            }
            for (int col = 0; col < columnCount; col++) {
                TableCell cell = new TableCell();
                float cellLeft = columnBoundaries.get(col);
                float cellRight = columnBoundaries.get(col + 1);
                cell.setX1(cellLeft);
                cell.setY1(row.getTop());
                cell.setX2(cellRight);
                cell.setY2(row.getTop());
                cell.setX3(cellRight);
                cell.setY3(row.getBottom());
                cell.setX4(cellLeft);
                cell.setY4(row.getBottom());
                cell.setRowindex(rowIndex);
                cell.setColindex(col);
                cell.setRowspan(1);
                cell.setColspan(1);
                cell.setWords(wordsPerColumn.get(col));
                cell.setHeaderOrFooterCell(row.isHeader());
                rowCells.put(col, cell);
            }
            cells.put(rowIndex, rowCells);
        }
        table.setCells(cells);
        return table;
    }

    private static int columnIndexFor(List<Float> columnBoundaries, float centerX) {
        int columnCount = columnBoundaries.size() - 1;
        for (int col = 0; col < columnCount; col++) {
            if (centerX < columnBoundaries.get(col + 1)) {
                return col;
            }
        }
        return columnCount - 1;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;

import java.util.List;

/**
 * A native (offline) transaction-table extractor for one supported layout family.
 */
public interface NativeTableExtractor {

    NativeLayoutPolicy getPolicy();

    /**
     * Extracts candidate transaction tables from a single page.
     *
     * @param page    the native content of the page
     * @param context shared per-document extraction context (e.g. the column model
     *                carried over from a previous page)
     * @return the extracted tables, or an empty list when the page does not match
     * this layout family
     */
    List<Table> extractTables(NativePdfPageContent page, NativeExtractionContext context);
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import lombok.Data;

import java.util.List;

/**
 * Mutable per-document state shared between the page-level native extraction calls.
 * Allows continuation pages without a repeated header to reuse the column model
 * discovered on an earlier page.
 */
@Data
public class NativeExtractionContext {
    private List<Float> lastColumnBoundaries;
    private int lastDateColumnIndex = -1;
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeTableSupport.LogicalRow;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

/**
 * Native extractor for fully ruled ("bordered grid") statement tables: rows and
 * columns are both delimited by drawn lines (possibly dashed). Cells are recovered
 * from the ruling intersections; row bands that contain several date-anchored text
 * lines (partially ruled grids) are subdivided using the text lines.
 */
@Component
@Slf4j
public class BorderedGridTableExtractor implements NativeTableExtractor {

    private static final float MIN_HORIZONTAL_RULING_LENGTH = 1.0f;
    private static final float MIN_VERTICAL_RULING_LENGTH = 0.15f;
    private static final float REGION_LINE_OVERLAP_RATIO = 0.5f;
    private static final float MAX_ROW_BAND_GAP = 1.6f;
    private static final float BOUNDARY_CLUSTER_TOLERANCE = 0.06f;
    private static final float CONTINUATION_GAP = 0.4f;
    private static final int MIN_COLUMNS = 3;
    private static final int MIN_ROW_LINES = 3;

    @Override
    public NativeLayoutPolicy getPolicy() {
        return NativeLayoutPolicy.BORDERED_GRID;
    }

    @Override
    public List<Table> extractTables(NativePdfPageContent page, NativeExtractionContext context) {
        List<Table> tables = new LinkedList<>();

        List<NativeRuling> horizontals = page.getHorizontalRulings().stream()
                .filter(ruling -> ruling.length() >= MIN_HORIZONTAL_RULING_LENGTH)
                .toList();
        List<NativeRuling> verticals = page.getVerticalRulings().stream()
                .filter(ruling -> ruling.length() >= MIN_VERTICAL_RULING_LENGTH)
                .toList();

        for (List<NativeRuling> region : groupIntoRegions(horizontals)) {
            Table table = extractRegionTable(page, region, verticals, context);
            if (table != null) {
                tables.add(table);
            }
        }
        return tables;
    }

    /**
     * Groups horizontal rulings into vertically stacked regions of lines with a
     * similar horizontal extent.
     */
    private List<List<NativeRuling>> groupIntoRegions(List<NativeRuling> horizontals) {
        List<NativeRuling> sorted = new ArrayList<>(horizontals);
        sorted.sort((a, b) -> Float.compare(a.position(), b.position()));

        List<List<NativeRuling>> regions = new LinkedList<>();
        List<NativeRuling> current = null;
        NativeRuling previous = null;
        for (NativeRuling ruling : sorted) {
            boolean sameRegion = false;
            if (previous != null && current != null) {
                float overlap = ruling.overlap(previous);
                float minLength = Math.min(ruling.length(), previous.length());
                sameRegion = overlap >= REGION_LINE_OVERLAP_RATIO * minLength
                        && ruling.position() - previous.position() <= MAX_ROW_BAND_GAP;
            }
            if (!sameRegion) {
                current = new LinkedList<>();
                regions.add(current);
            }
            current.add(ruling);
            previous = ruling;
        }
        return regions.stream().filter(region -> region.size() >= MIN_ROW_LINES).toList();
    }

    private Table extractRegionTable(NativePdfPageContent page, List<NativeRuling> regionLines,
                                     List<NativeRuling> verticals, NativeExtractionContext context) {
        float top = regionLines.get(0).position();
        float bottom = regionLines.get(regionLines.size() - 1).position();
        float left = Float.MAX_VALUE;
        float right = -Float.MAX_VALUE;
        for (NativeRuling line : regionLines) {
            left = Math.min(left, line.start());
            right = Math.max(right, line.end());
        }
        float regionHeight = bottom - top;
        if (regionHeight < 0.2f) {
            return null;
        }

        // Column boundaries from the vertical rulings crossing this region
        List<Float> verticalPositions = new ArrayList<>();
        for (NativeRuling vertical : verticals) {
            if (vertical.position() < left - 0.06f || vertical.position() > right + 0.06f) {
                continue;
            }
            float overlapStart = Math.max(vertical.start(), top);
            float overlapEnd = Math.min(vertical.end(), bottom);
            float overlap = Math.max(0f, overlapEnd - overlapStart);
            if (overlap >= 0.2f * regionHeight || overlap >= 0.6f * vertical.length()) {
                verticalPositions.add(vertical.position());
            }
        }
        List<Float> boundaries = NativeTableSupport.clusterPositions(verticalPositions, BOUNDARY_CLUSTER_TOLERANCE);
        if (boundaries.isEmpty() || Math.abs(boundaries.get(0) - left) > 0.08f) {
            boundaries.add(0, left);
        }
        if (Math.abs(boundaries.get(boundaries.size() - 1) - right) > 0.08f) {
            boundaries.add(right);
        }
        if (boundaries.size() - 1 < MIN_COLUMNS) {
            return null;
        }

        // Row bands from the horizontal rulings
        List<Float> rowBoundaries = NativeTableSupport.clusterPositions(
                regionLines.stream().map(NativeRuling::position).toList(), 0.04f);
        if (rowBoundaries.size() < MIN_ROW_LINES) {
            return null;
        }

        // Words in region
        List<Word> regionWords = new LinkedList<>();
        for (Word word : page.getWords()) {
            float centerX = (word.getX1() + word.getX3()) / 2f;
            float centerY = (word.getY1() + word.getY3()) / 2f;
            if (centerX >= left - 0.03f && centerX <= right + 0.03f
                    && centerY >= top - 0.02f && centerY <= bottom + 0.02f) {
                regionWords.add(word);
            }
        }
        if (regionWords.isEmpty()) {
            return null;
        }

        // First pass: band words + header band detection
        int bandCount = rowBoundaries.size() - 1;
        List<List<Word>> bandWords = new ArrayList<>();
        for (int band = 0; band < bandCount; band++) {
            bandWords.add(new LinkedList<>());
        }
        for (Word word : regionWords) {
            float centerY = (word.getY1() + word.getY3()) / 2f;
            int band = bandIndexFor(rowBoundaries, centerY);
            if (band >= 0) {
                bandWords.get(band).add(word);
            }
        }

        int headerBand = -1;
        List<NativeTextLine> headerLines = new LinkedList<>();
        List<NativeTextLine> dataLines = new LinkedList<>();
        List<List<NativeTextLine>> bandLines = new ArrayList<>();
        for (int band = 0; band < bandCount; band++) {
            List<NativeTextLine> lines = NativeTableSupport.buildTextLines(bandWords.get(band));
            bandLines.add(lines);
            String bandContent = lines.stream().map(NativeTextLine::content)
                    .reduce("", (a, b) -> a + " " + b);
            if (headerBand < 0 && band <= 2 && NativeTableSupport.isTransactionHeaderLine(bandContent)) {
                headerBand = band;
                headerLines.addAll(lines);
            } else {
                dataLines.addAll(lines);
            }
        }

        int dateColumn = NativeTableSupport.findDateColumnIndex(boundaries, headerLines, dataLines);
        if (dateColumn < 0 && context.getLastDateColumnIndex() >= 0
                && context.getLastDateColumnIndex() < boundaries.size() - 1) {
            dateColumn = context.getLastDateColumnIndex();
        }

        // Second pass: build logical rows band by band
        List<LogicalRow> rows = new LinkedList<>();
        for (int band = 0; band < bandCount; band++) {
            List<NativeTextLine> lines = bandLines.get(band);
            if (lines.isEmpty()) {
                continue;
            }
            float bandTop = rowBoundaries.get(band);
            float bandBottom = rowBoundaries.get(band + 1);
            if (band == headerBand) {
                LogicalRow headerRow = new LogicalRow(bandTop, bandBottom, true);
                headerRow.addWords(bandWords.get(band));
                rows.add(headerRow);
                continue;
            }
            List<LogicalRow> subRows = null;
            if (dateColumn >= 0) {
                float dateLeft = boundaries.get(dateColumn);
                float dateRight = boundaries.get(dateColumn + 1);
                long anchorCount = lines.stream()
                        .filter(line -> NativeTableSupport.containsDate(line.contentBetween(dateLeft, dateRight)))
                        .count();
                if (anchorCount >= 2) {
                    // Partially ruled grid: the band holds several transactions
                    subRows = NativeTableSupport.groupLinesIntoRows(lines, dateLeft, dateRight, CONTINUATION_GAP);
                }
            }
            if (subRows != null && !subRows.isEmpty()) {
                rows.addAll(subRows);
            } else {
                LogicalRow row = new LogicalRow(bandTop, bandBottom, false);
                row.addWords(bandWords.get(band));
                rows.add(row);
            }
        }

        long dataRows = rows.stream().filter(row -> !row.isHeader()).count();
        if (rows.isEmpty() || dataRows < 1) {
            return null;
        }

        if (dateColumn >= 0) {
            context.setLastColumnBoundaries(boundaries);
            context.setLastDateColumnIndex(dateColumn);
        }
        return NativeTableSupport.buildTable(page.getPageNumber(), boundaries, rows);
    }

    private int bandIndexFor(List<Float> rowBoundaries, float centerY) {
        for (int band = 0; band < rowBoundaries.size() - 1; band++) {
            if (centerY >= rowBoundaries.get(band) && centerY < rowBoundaries.get(band + 1)) {
                return band;
            }
        }
        return -1;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeTableSupport.LogicalRow;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

/**
 * Native extractor for "box guided" statement tables: vertical column separators
 * (or repeated boxes) delimit the columns, but the individual transaction rows are
 * not ruled. Rows are recovered from the text lines, anchored on lines carrying a
 * date in the transaction-date column; unanchored lines are folded into the row
 * above them (multi-line narrations).
 */
@Component
@Slf4j
public class BoxGuidedTableExtractor implements NativeTableExtractor {

    private static final float MIN_VERTICAL_RULING_LENGTH = 0.4f;
    private static final float BOUNDARY_CLUSTER_TOLERANCE = 0.06f;
    private static final float MIN_BOUNDARY_COVERAGE_RATIO = 0.25f;
    private static final float CONTINUATION_GAP = 0.45f;
    private static final int MIN_COLUMNS = 3;

    @Override
    public NativeLayoutPolicy getPolicy() {
        return NativeLayoutPolicy.BOX_GUIDED;
    }

    @Override
    public List<Table> extractTables(NativePdfPageContent page, NativeExtractionContext context) {
        List<NativeRuling> verticals = page.getVerticalRulings().stream()
                .filter(ruling -> ruling.length() >= MIN_VERTICAL_RULING_LENGTH)
                .toList();
        if (verticals.isEmpty()) {
            return List.of();
        }

        float regionTop = Float.MAX_VALUE;
        float regionBottom = -Float.MAX_VALUE;
        for (NativeRuling vertical : verticals) {
            regionTop = Math.min(regionTop, vertical.start());
            regionBottom = Math.max(regionBottom, vertical.end());
        }
        float regionHeight = regionBottom - regionTop;
        if (regionHeight < 0.5f) {
            return List.of();
        }

        // Column boundaries: x clusters of vertical separators with enough coverage
        List<Float> clusterCenters = NativeTableSupport.clusterPositions(
                verticals.stream().map(NativeRuling::position).toList(), BOUNDARY_CLUSTER_TOLERANCE);
        List<Float> boundaries = new ArrayList<>();
        for (Float center : clusterCenters) {
            float coverage = 0f;
            for (NativeRuling vertical : verticals) {
                if (Math.abs(vertical.position() - center) <= BOUNDARY_CLUSTER_TOLERANCE) {
                    coverage += vertical.length();
                }
            }
            if (coverage >= MIN_BOUNDARY_COVERAGE_RATIO * regionHeight) {
                boundaries.add(center);
            }
        }
        if (boundaries.size() - 1 < MIN_COLUMNS) {
            return List.of();
        }

        float left = boundaries.get(0);
        float right = boundaries.get(boundaries.size() - 1);

        // Words inside the boxed region
        List<Word> regionWords = new LinkedList<>();
        for (Word word : page.getWords()) {
            float centerX = (word.getX1() + word.getX3()) / 2f;
            float centerY = (word.getY1() + word.getY3()) / 2f;
            if (centerX >= left - 0.03f && centerX <= right + 0.03f
                    && centerY >= regionTop - 0.05f && centerY <= regionBottom + 0.05f) {
                regionWords.add(word);
            }
        }
        if (regionWords.isEmpty()) {
            return List.of();
        }

        List<NativeTextLine> lines = NativeTableSupport.buildTextLines(regionWords);

        // Leading header lines: everything before the first date-anchored data line
        // that still looks like a column-label line.
        List<NativeTextLine> headerLines = new LinkedList<>();
        List<NativeTextLine> dataLines = new LinkedList<>();
        boolean dataStarted = false;
        for (NativeTextLine line : lines) {
            if (!dataStarted && NativeTableSupport.containsDate(line.content())
                    && NativeTableSupport.containsAmount(line.content())) {
                dataStarted = true;
            }
            if (!dataStarted && NativeTableSupport.headerKeywordGroupCount(line.content()) >= 2) {
                headerLines.add(line);
            } else if (dataStarted) {
                dataLines.add(line);
            }
        }

        int dateColumn = NativeTableSupport.findDateColumnIndex(boundaries, headerLines, dataLines);
        if (dateColumn < 0 && context.getLastDateColumnIndex() >= 0
                && context.getLastDateColumnIndex() < boundaries.size() - 1) {
            dateColumn = context.getLastDateColumnIndex();
        }
        if (dateColumn < 0) {
            return List.of();
        }

        float dateLeft = boundaries.get(dateColumn);
        float dateRight = boundaries.get(dateColumn + 1);
        List<LogicalRow> rows = new LinkedList<>();
        if (!headerLines.isEmpty()) {
            LogicalRow headerRow = LogicalRow.fromLine(headerLines.get(0), true);
            for (int i = 1; i < headerLines.size(); i++) {
                headerRow.addLine(headerLines.get(i));
            }
            // Re-create as header row (fromLine defaults preserved above)
            LogicalRow header = new LogicalRow(headerRow.getTop(), headerRow.getBottom(), true);
            header.addWords(headerRow.getWords());
            rows.add(header);
        }
        List<LogicalRow> dataRows = NativeTableSupport.groupLinesIntoRows(dataLines, dateLeft, dateRight, CONTINUATION_GAP);
        if (dataRows.isEmpty()) {
            return List.of();
        }
        rows.addAll(dataRows);

        context.setLastColumnBoundaries(boundaries);
        context.setLastDateColumnIndex(dateColumn);
        return List.of(NativeTableSupport.buildTable(page.getPageNumber(), boundaries, rows));
    }
}

