package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeTableSupport.LogicalRow;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Locale;

/**
 * Native extractor for statements without usable rulings ("text aligned,
 * row selected"): the column model is derived from the alignment of the header
 * labels, transaction rows are selected by date-anchored text lines and unanchored
 * lines are folded into the row above them. Continuation pages without a repeated
 * header reuse the column model of the previous page.
 */
@Component
@Slf4j
public class TextAlignedRowSelectedTableExtractor implements NativeTableExtractor {

    private static final float HEADER_GROUP_GAP = 0.14f;
    private static final float SECOND_HEADER_LINE_GAP = 0.16f;
    private static final float CONTINUATION_GAP = 0.4f;
    private static final float PAGE_MARGIN = 0.05f;
    private static final int MIN_COLUMNS = 3;

    private static final String[] TABLE_END_MARKERS = {
            "statement summary", "end of statement", "end of the statement", "grand total",
            "legends", "abbreviations", "registered office", "this is a computer generated"
    };

    @Override
    public NativeLayoutPolicy getPolicy() {
        return NativeLayoutPolicy.TEXT_ALIGNED_ROW_SELECTED;
    }

    @Override
    public List<Table> extractTables(NativePdfPageContent page, NativeExtractionContext context) {
        List<NativeTextLine> lines = NativeTableSupport.buildTextLines(page.getWords());
        if (lines.isEmpty()) {
            return List.of();
        }

        int headerIndex = findHeaderLineIndex(lines);
        List<Float> boundaries;
        int dateColumn;
        List<NativeTextLine> headerLines = new LinkedList<>();
        int dataStartIndex;

        if (headerIndex >= 0) {
            headerLines.add(lines.get(headerIndex));
            // Two-line headers: absorb the next line when it is close and carries no data
            int next = headerIndex + 1;
            if (next < lines.size()
                    && lines.get(next).getTop() - lines.get(headerIndex).getBottom() <= SECOND_HEADER_LINE_GAP
                    && !NativeTableSupport.containsDate(lines.get(next).content())
                    && !NativeTableSupport.containsAmount(lines.get(next).content())) {
                headerLines.add(lines.get(next));
            }
            dataStartIndex = headerIndex + headerLines.size();
            boundaries = boundariesFromHeader(headerLines.get(0), lines.subList(dataStartIndex, lines.size()), page);
            if (boundaries == null || boundaries.size() - 1 < MIN_COLUMNS) {
                return List.of();
            }
            dateColumn = NativeTableSupport.findDateColumnIndex(boundaries, headerLines,
                    lines.subList(dataStartIndex, lines.size()));
        } else {
            // Continuation page: reuse the column model of a previous page
            boundaries = context.getLastColumnBoundaries();
            dateColumn = context.getLastDateColumnIndex();
            dataStartIndex = 0;
            if (boundaries == null || boundaries.size() - 1 < MIN_COLUMNS || dateColumn < 0) {
                return List.of();
            }
        }
        if (dateColumn < 0 || dateColumn >= boundaries.size() - 1) {
            return List.of();
        }

        // Data lines: below the header, until an end-of-table marker
        List<NativeTextLine> dataLines = new LinkedList<>();
        for (int i = dataStartIndex; i < lines.size(); i++) {
            NativeTextLine line = lines.get(i);
            if (isTableEndLine(line)) {
                break;
            }
            dataLines.add(line);
        }

        float dateLeft = boundaries.get(dateColumn);
        float dateRight = boundaries.get(dateColumn + 1);
        List<LogicalRow> dataRows = NativeTableSupport.groupLinesIntoRows(dataLines, dateLeft, dateRight, CONTINUATION_GAP);
        // Keep only rows that actually look like transactions (date + some amount)
        List<LogicalRow> rows = new LinkedList<>();
        if (!headerLines.isEmpty()) {
            LogicalRow header = LogicalRow.fromLine(headerLines.get(0), true);
            for (int i = 1; i < headerLines.size(); i++) {
                header.addLine(headerLines.get(i));
            }
            rows.add(header);
        }
        for (LogicalRow row : dataRows) {
            String content = rowContent(row);
            if (NativeTableSupport.containsAmount(content)) {
                rows.add(row);
            }
        }
        long transactionRows = rows.stream().filter(row -> !row.isHeader()).count();
        if (transactionRows < 1) {
            return List.of();
        }

        context.setLastColumnBoundaries(boundaries);
        context.setLastDateColumnIndex(dateColumn);
        return List.of(NativeTableSupport.buildTable(page.getPageNumber(), boundaries, rows));
    }

    private int findHeaderLineIndex(List<NativeTextLine> lines) {
        for (int i = 0; i < lines.size(); i++) {
            if (!NativeTableSupport.isTransactionHeaderLine(lines.get(i).content())) {
                continue;
            }
            // Require at least two date-anchored lines somewhere below the header
            int anchors = 0;
            for (int j = i + 1; j < lines.size() && anchors < 2; j++) {
                String content = lines.get(j).content();
                if (NativeTableSupport.containsDate(content) && NativeTableSupport.containsAmount(content)) {
                    anchors++;
                }
            }
            if (anchors >= 1) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Derives the column boundaries from the header label groups, refined by the
     * horizontal extent of the data below the header.
     */
    private List<Float> boundariesFromHeader(NativeTextLine headerLine, List<NativeTextLine> dataLines,
                                             NativePdfPageContent page) {
        List<float[]> groups = new ArrayList<>(); // {left, right}
        float[] current = null;
        for (Word word : headerLine.getWords()) {
            if (current != null && word.getX1() - current[1] <= HEADER_GROUP_GAP) {
                current[1] = Math.max(current[1], word.getX3());
            } else {
                current = new float[]{word.getX1(), word.getX3()};
                groups.add(current);
            }
        }
        if (groups.size() < MIN_COLUMNS) {
            return null;
        }

        float dataMinX = groups.get(0)[0];
        float dataMaxX = groups.get(groups.size() - 1)[1];
        for (NativeTextLine line : dataLines) {
            if (line.getWords().isEmpty()) {
                continue;
            }
            dataMinX = Math.min(dataMinX, line.minX());
            dataMaxX = Math.max(dataMaxX, line.maxX());
        }

        List<Float> boundaries = new ArrayList<>();
        boundaries.add(Math.max(0f, Math.min(dataMinX, groups.get(0)[0]) - PAGE_MARGIN));
        for (int i = 0; i < groups.size() - 1; i++) {
            boundaries.add((groups.get(i)[1] + groups.get(i + 1)[0]) / 2f);
        }
        boundaries.add(Math.min(page.getWidth(), Math.max(dataMaxX, groups.get(groups.size() - 1)[1]) + PAGE_MARGIN));
        return boundaries;
    }

    private boolean isTableEndLine(NativeTextLine line) {
        String content = line.content().toLowerCase(Locale.ROOT);
        for (String marker : TABLE_END_MARKERS) {
            if (content.contains(marker)) {
                return true;
            }
        }
        return false;
    }

    private String rowContent(LogicalRow row) {
        StringBuilder builder = new StringBuilder();
        for (Word word : row.getWords()) {
            if (builder.length() > 0) {
                builder.append(' ');
            }
            builder.append(word.getContent());
        }
        return builder.toString();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import org.springframework.stereotype.Component;

import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

import static com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeLayoutPolicy.BORDERED_GRID;
import static com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeLayoutPolicy.BOX_GUIDED;
import static com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeLayoutPolicy.TEXT_ALIGNED_ROW_SELECTED;

/**
 * Maps the supported bank-format families to the native extraction policies that
 * should be attempted for them, in order of preference. The mapping reflects the
 * dominant layout of each bank family in the statement fixture corpus
 * (src/test/resources/pdf-samples-latest); banks with mixed corpora list a
 * secondary policy. Unknown banks get no native policy and stay on the remote ML
 * path.
 */
@Component
public class NativeExtractionPolicyRegistry {

    private final Map<String, List<NativeLayoutPolicy>> policiesByBank = new HashMap<>();

    public NativeExtractionPolicyRegistry() {
        // Fully ruled grid statements
        register("AHMEDNAGAR", BORDERED_GRID);
        register("BANDHAN", BORDERED_GRID);
        register("DEUSTCHE", BORDERED_GRID);
        register("DEUTSCHE", BORDERED_GRID);
        register("FEDERAL", BORDERED_GRID);
        register("GS_MAHANAGAR_CO_OP_BANK", BORDERED_GRID);
        register("IDBI", BORDERED_GRID);
        register("IDFC", BORDERED_GRID);
        register("INDIAN", BORDERED_GRID);
        register("STANDARD_CHARTERED", BORDERED_GRID);
        register("TJSB_BANK", BORDERED_GRID);
        register("YES", BORDERED_GRID);

        // Grid dominant with text-aligned variants in the corpus
        register("CBI", BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register("HDFC", BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register("INDIAN_OVERSEAS", BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register("KOTAK", BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register("PNB", BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register("UNION", BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED);
        register("INDUSIND", BORDERED_GRID, BOX_GUIDED);

        // Box guided (vertical separators only)
        register("ICICI", BOX_GUIDED, TEXT_ALIGNED_ROW_SELECTED);
        register("RBL", BOX_GUIDED, TEXT_ALIGNED_ROW_SELECTED);
        register("SBI", BOX_GUIDED, BORDERED_GRID);
        register("SURYODAY_SMALL_FINANCE_BANK_LTD", BOX_GUIDED);

        // No rulings: text aligned, row selected
        register("AXIS", TEXT_ALIGNED_ROW_SELECTED);
        register("BOB", TEXT_ALIGNED_ROW_SELECTED);
        register("CITI", TEXT_ALIGNED_ROW_SELECTED);
    }

    private void register(String bankCode, NativeLayoutPolicy... policies) {
        policiesByBank.put(bankCode, List.of(policies));
    }

    /**
     * @return the ordered native policies to attempt for the given bank, or an empty
     * list when the bank family is not supported by the native path.
     */
    public List<NativeLayoutPolicy> policiesFor(String bankCode) {
        if (bankCode == null || bankCode.isBlank()) {
            return List.of();
        }
        String normalized = bankCode.trim().toUpperCase(Locale.ROOT).replaceAll("[\\s-]+", "_");
        return policiesByBank.getOrDefault(normalized, List.of());
    }

    public boolean isNativeSupported(String bankCode) {
        return !policiesFor(bankCode).isEmpty();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeTableSupport.LogicalRow;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.io.File;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Offline, in-process transaction-table extraction for supported bank statement
 * layouts. Produces the same {@link DocumentExtractionResult} structure as the
 * remote ML path so a successful native result can be carried through the regular
 * downstream document analysis untouched.
 */
@Service
@Slf4j
public class NativeTableExtractionService {

    /** Minimum number of words for a document to be considered an electronic PDF. */
    private static final int MIN_TEXT_WORDS = 40;
    /** Minimum number of transaction-like data rows for a native result to be accepted. */
    private static final int MIN_TOTAL_DATA_ROWS = 2;

    private final NativePdfContentReader contentReader;
    private final List<NativeTableExtractor> extractors;

    public NativeTableExtractionService(NativePdfContentReader contentReader,
                                        List<NativeTableExtractor> extractors) {
        this.contentReader = contentReader;
        this.extractors = extractors;
    }

    /**
     * Attempts the native extraction policies in order and returns the first result
     * that passes plausibility validation.
     *
     * @return a populated {@link DocumentExtractionResult} with
     * {@code extractionMode = NATIVE}, or empty when no policy succeeds
     */
    public Optional<DocumentExtractionResult> extract(File pdfFile, List<NativeLayoutPolicy> policies) {
        if (pdfFile == null || policies == null || policies.isEmpty()) {
            return Optional.empty();
        }

        List<NativePdfPageContent> pages;
        try {
            pages = contentReader.readPages(pdfFile);
        } catch (Exception e) {
            log.info("Native PDF content extraction not possible for {}: {}", pdfFile.getName(), e.getMessage());
            return Optional.empty();
        }
        if (pages.isEmpty()) {
            return Optional.empty();
        }

        int totalWords = pages.stream().mapToInt(page -> page.getWords() != null ? page.getWords().size() : 0).sum();
        if (totalWords < MIN_TEXT_WORDS) {
            log.info("Document {} has no usable text layer ({} words); skipping native extraction",
                    pdfFile.getName(), totalWords);
            return Optional.empty();
        }

        for (NativeLayoutPolicy policy : policies) {
            NativeTableExtractor extractor = extractorFor(policy);
            if (extractor == null) {
                continue;
            }
            try {
                DocumentExtractionResult result = extractWithPolicy(pages, extractor);
                if (result != null) {
                    log.info("Native table extraction succeeded for {} using policy {}",
                            pdfFile.getName(), policy);
                    return Optional.of(result);
                }
                log.info("Native policy {} did not produce a plausible result for {}", policy, pdfFile.getName());
            } catch (Exception e) {
                log.warn("Native policy {} failed for {}: {}", policy, pdfFile.getName(), e.getMessage());
            }
        }
        return Optional.empty();
    }

    private NativeTableExtractor extractorFor(NativeLayoutPolicy policy) {
        return extractors.stream()
                .filter(extractor -> extractor.getPolicy() == policy)
                .findFirst()
                .orElse(null);
    }

    private DocumentExtractionResult extractWithPolicy(List<NativePdfPageContent> pages,
                                                       NativeTableExtractor extractor) {
        NativeExtractionContext context = new NativeExtractionContext();
        Map<Integer, Page> resultPages = new HashMap<>();
        int totalDataRows = 0;
        boolean coverageSatisfied = true;

        for (NativePdfPageContent pageContent : pages) {
            List<Table> tables = extractor.extractTables(pageContent, context);

            Page page = new Page();
            page.setPageNumber(pageContent.getPageNumber());
            page.setWidth((double) pageContent.getWidth());
            page.setHeight((double) pageContent.getHeight());
            page.setWords(pageContent.getWords() != null ? pageContent.getWords() : new ArrayList<>());
            page.setContent(pageContent.getText() != null ? pageContent.getText() : "");

            Map<Integer, Table> tableMap = new LinkedHashMap<>();
            int tableIndex = 0;
            for (Table table : tables) {
                tableMap.put(tableIndex++, table);
            }
            page.setTables(tableMap);
            resultPages.put(pageContent.getPageNumber(), page);

            int pageDataRows = countTransactionLikeRows(tables);
            totalDataRows += pageDataRows;

            int candidateLines = countTransactionCandidateLines(pageContent);
            if (candidateLines >= 3 && pageDataRows < Math.max(1, candidateLines / 2)) {
                // The page clearly contains transaction lines the policy did not capture.
                coverageSatisfied = false;
            }
        }

        if (!coverageSatisfied || totalDataRows < MIN_TOTAL_DATA_ROWS) {
            return null;
        }

        DocumentExtractionResult result = new DocumentExtractionResult();
        result.setPages(resultPages);
        result.setNoOfPages(pages.size());
        return result;
    }

    /**
     * Counts non-header table rows carrying both a date-like and an amount-like token.
     */
    private int countTransactionLikeRows(List<Table> tables) {
        int count = 0;
        for (Table table : tables) {
            if (table.getCells() == null) {
                continue;
            }
            for (Map<Integer, TableCell> row : table.getCells().values()) {
                boolean header = false;
                StringBuilder content = new StringBuilder();
                for (TableCell cell : row.values()) {
                    header |= cell.isHeaderOrFooterCell();
                    content.append(' ').append(cell.getContent());
                }
                if (!header
                        && NativeTableSupport.containsDate(content.toString())
                        && NativeTableSupport.containsAmount(content.toString())) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Counts the text lines of the page that look like transaction rows (a date plus
     * an amount) - used to check that the native tables cover the page's content.
     */
    private int countTransactionCandidateLines(NativePdfPageContent pageContent) {
        if (pageContent.getWords() == null || pageContent.getWords().isEmpty()) {
            return 0;
        }
        List<NativeTextLine> lines = NativeTableSupport.buildTextLines(pageContent.getWords());
        int count = 0;
        for (NativeTextLine line : lines) {
            String content = line.content();
            if (NativeTableSupport.containsDate(content) && NativeTableSupport.containsAmount(content)) {
                count++;
            }
        }
        return count;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction;

import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.AnalyzeDocuments;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.EPdfCharacterExtractionService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

/**
 * The downstream document analysis applied to a mapped {@link DocumentExtractionResult},
 * independent of the engine (native offline or remote ML) that produced it:
 * character-level enhancement, bank specific handling, pre-process verification and
 * the table/column analysis.
 */
@Component
@Slf4j
public class DocumentAnalysisPipeline {

    private EPdfCharacterExtractionService ePdfCharacterExtractionService;
    private IBankSpecificParsingService bankSpecificParsingService;
    private AnalyzeDocuments analyzeDocuments;

    @Autowired
    public void setEPdfCharacterExtractionService(EPdfCharacterExtractionService ePdfCharacterExtractionService) {
        this.ePdfCharacterExtractionService = ePdfCharacterExtractionService;
    }

    @Autowired
    public void setBankSpecificParsingService(IBankSpecificParsingService bankSpecificParsingService) {
        this.bankSpecificParsingService = bankSpecificParsingService;
    }

    @Autowired
    public void setAnalyzeDocuments(AnalyzeDocuments analyzeDocuments) {
        this.analyzeDocuments = analyzeDocuments;
    }

    public DocumentExtractionResult analyze(DocumentExtractionResult result, DocumentExtractionRequest request) {
        // Enhance with character-level information right after mapping
        try {
            boolean enhanced = ePdfCharacterExtractionService.enhanceDocumentWithCharacterInfo(result, request.getStatementFile());
            if (enhanced) {
                log.info("Successfully enhanced document with character-level information");
            } else {
                log.info("Document could not be enhanced with character-level information (likely a scanned PDF)");
            }
        } catch (Exception e) {
            log.warn("Failed to enhance document with character-level information: {}", e.getMessage());
        }

        //check if the bank statement parsing happen bank specific
        bankSpecificParsingService.identifyBankSpecificStatementProcess(result, request);

        if (result.isSkipFurtherProcessing()) {
            return result;
        }

        int pageCount = result.getNoOfPages() != null ? result.getNoOfPages() : 0;

        // Continue with the rest of the processing
        DocumentExtractionResult preProcessedResultByHeader = analyzeDocuments.preProcessForVerificationByHeader(result, 5);
        if (preProcessedResultByHeader != null && preProcessedResultByHeader.getPreProcessVerificationResult() != null) {
            result.setPreProcessVerificationResult(preProcessedResultByHeader.getPreProcessVerificationResult());
        } else {
            DocumentExtractionResult preprocessedResult = analyzeDocuments.preProcessForVerification(result, pageCount);
            if (preprocessedResult != null && preprocessedResult.getPreProcessVerificationResult() != null) {
                result.setPreProcessVerificationResult(preprocessedResult.getPreProcessVerificationResult());
            }
        }
        analyzeDocuments.analyzeDocument(result, true, true, true);

        return result;
    }
}

