import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.ExtractionMode;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeExtractionPolicyRegistry;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeLayoutPolicy;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeTableExtractionService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Document extraction entry point that prefers the offline native transaction-table
 * path for supported bank-format families and keeps the remote ML path as the
 * default for unknown or unsupported layouts.
 *
 * <p>When a supported native layout succeeds, the native result is carried through
 * the same downstream document analysis as the ML result - without invoking the
 * remote ML extraction. When the native attempt does not produce a usable
 * transaction table, the service transparently falls back to the ML path and marks
 * the result as {@link ExtractionMode#NATIVE_FALLBACK_ML}.</p>
 */
@Service
@Slf4j
public class HybridDocumentExtractionServiceImpl implements DocumentExtractionService {

    private NativeTableExtractionService nativeTableExtractionService;
    private NativeExtractionPolicyRegistry nativeExtractionPolicyRegistry;
    private DocumentAnalysisPipeline documentAnalysisPipeline;
    private DocumentExtractionService azureDocumentExtractionService;

    @Autowired
    public void setNativeTableExtractionService(NativeTableExtractionService nativeTableExtractionService) {
        this.nativeTableExtractionService = nativeTableExtractionService;
    }

    @Autowired
    public void setNativeExtractionPolicyRegistry(NativeExtractionPolicyRegistry nativeExtractionPolicyRegistry) {
        this.nativeExtractionPolicyRegistry = nativeExtractionPolicyRegistry;
    }

    @Autowired
    public void setDocumentAnalysisPipeline(DocumentAnalysisPipeline documentAnalysisPipeline) {
        this.documentAnalysisPipeline = documentAnalysisPipeline;
    }

    @Autowired
    @Qualifier("azureDocumentExtractionServiceImpl")
    public void setAzureDocumentExtractionService(DocumentExtractionService azureDocumentExtractionService) {
        this.azureDocumentExtractionService = azureDocumentExtractionService;
    }

    @Override
    public DocumentExtractionResult extractDocument(BankStatementVO bankStatementVO) throws IOException {
        DocumentExtractionRequest documentExtractionRequest = new DocumentExtractionRequest();
        documentExtractionRequest.setStatementFile(bankStatementVO.getDecryptedFile());
        documentExtractionRequest.setBankName(bankStatementVO.getBank());
        try {
            documentExtractionRequest.setStatementFromDate(BankStatementProcessorImpl.parseDate(bankStatementVO.getBankAccountDetailsVO().getStatementFrom()));
        } catch (Exception e) {
            log.warn("Failed to parse statement-from-date from date string {}", bankStatementVO.getBankAccountDetailsVO().getStatementFrom());
        }
        return extractDocument(documentExtractionRequest);
    }

    @Override
    public DocumentExtractionResult extractDocument(DocumentExtractionRequest request) throws IOException {
        List<NativeLayoutPolicy> policies = nativeExtractionPolicyRegistry.policiesFor(request.getBankName());
        boolean nativeAttempted = false;

        if (!policies.isEmpty()) {
            nativeAttempted = true;
            try {
                Optional<DocumentExtractionResult> nativeResult =
                        nativeTableExtractionService.extract(request.getStatementFile(), policies);
                if (nativeResult.isPresent()) {
                    DocumentExtractionResult result = documentAnalysisPipeline.analyze(nativeResult.get(), request);
                    result.setExtractionMode(ExtractionMode.NATIVE);
                    if (result.isSkipFurtherProcessing() || hasTransactionTable(result)) {
                        log.info("Using native transaction-table extraction for bank {}", request.getBankName());
                        return result;
                    }
                    log.info("Downstream analysis did not confirm a transaction table in the native result " +
                            "for bank {}; falling back to ML extraction", request.getBankName());
                }
            } catch (Exception e) {
                log.warn("Native extraction attempt failed for bank {}: {}; falling back to ML extraction",
                        request.getBankName(), e.getMessage());
            }
        }

        DocumentExtractionResult mlResult = azureDocumentExtractionService.extractDocument(request);
        mlResult.setExtractionMode(nativeAttempted ? ExtractionMode.NATIVE_FALLBACK_ML : ExtractionMode.ML);
        return mlResult;
    }

    private boolean hasTransactionTable(DocumentExtractionResult result) {
        if (result == null || result.getPages() == null) {
            return false;
        }
        for (Page page : result.getPages().values()) {
            if (page.getTables() == null) {
                continue;
            }
            for (Table table : page.getTables().values()) {
                if (table.getIsTransactionTable() && table.getCells() != null && !table.getCells().isEmpty()) {
                    return true;
                }
            }
        }
        return false;
    }
}

