import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.bankAccount.BankTransactionVO;
import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.DocumentAnalysisPipeline;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankSpecificParsingServiceImpl;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.bank.*;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.*;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.*;

import java.io.File;
import java.util.*;

/**
 * Offline harness: runs the native table extraction + the downstream analysis
 * pipeline over the fixture corpus and reports per-file outcomes.
 */
public class NativeHarness {

    public static void main(String[] args) throws Exception {
        // Manual wiring of the downstream analysis pipeline
        ColumnTypeIdentifier columnTypeIdentifier = new ColumnTypeIdentifier();
        TableColumnNormalizer tableColumnNormalizer = new TableColumnNormalizer();
        TableRowNormalizer tableRowNormalizer = new TableRowNormalizer();
        BankTransactionRowNormalizer bankTransactionRowNormalizer = new BankTransactionRowNormalizer();
        BankTransactionTableHeaderIdentifier headerIdentifier = new BankTransactionTableHeaderIdentifier();
        headerIdentifier.setColumnTypeIdentifier(columnTypeIdentifier);
        BankTransactionTableFooterIdentifier footerIdentifier = new BankTransactionTableFooterIdentifier();
        BankTransactionColumnTypeIdentifier bankTransactionColumnTypeIdentifier = new BankTransactionColumnTypeIdentifier();
        BankTransactionTableIdentifier bankTransactionTableIdentifier = new BankTransactionTableIdentifier();

        HdfcBankUtil hdfcBankUtil = new HdfcBankUtil();
        setField(hdfcBankUtil, "tableColumnNormalizer", tableColumnNormalizer);
        setField(hdfcBankUtil, "tableRowNormalizer", tableRowNormalizer);
        MayBankUtil mayBankUtil = new MayBankUtil();
        mayBankUtil.setBankTransactionRowNormalizer(bankTransactionRowNormalizer);
        mayBankUtil.setBankTransactionTableHeaderIdentifier(headerIdentifier);
        PublicBankUtil publicBankUtil = new PublicBankUtil();
        publicBankUtil.setBankTransactionRowNormalizer(bankTransactionRowNormalizer);
        publicBankUtil.setBankTransactionTableHeaderIdentifier(headerIdentifier);
        SaraswatBankUtil saraswatBankUtil = new SaraswatBankUtil();
        saraswatBankUtil.setBankTransactionRowNormalizer(bankTransactionRowNormalizer);
        saraswatBankUtil.setBankTransactionTableHeaderIdentifier(headerIdentifier);
        StandardCharteredBankUtil scBankUtil = new StandardCharteredBankUtil();
        scBankUtil.setBankTransactionRowNormalizer(bankTransactionRowNormalizer);
        CatholicSyrianBankUtil csBankUtil = new CatholicSyrianBankUtil();

        BankSpecificParsingServiceImpl bankSpecific = new BankSpecificParsingServiceImpl();
        bankSpecific.setHdfcBankUtil(hdfcBankUtil);
        bankSpecific.setMayBankUtil(mayBankUtil);
        bankSpecific.setPublicBankUtil(publicBankUtil);
        bankSpecific.setSaraswatBankUtil(saraswatBankUtil);
        bankSpecific.setStandardCharteredBankUtil(scBankUtil);
        bankSpecific.setCatholicSyrianBankUtil(csBankUtil);

        AnalyzeDocuments analyzeDocuments = new AnalyzeDocuments();
        analyzeDocuments.setColumnTypeIdentifier(columnTypeIdentifier);
        analyzeDocuments.setBankTransactionColumnTypeIdentifier(bankTransactionColumnTypeIdentifier);
        analyzeDocuments.setBankTransactionTableIdentifier(bankTransactionTableIdentifier);
        analyzeDocuments.setTableColumnNormalizer(tableColumnNormalizer);
        analyzeDocuments.setTableRowNormalizer(tableRowNormalizer);
        analyzeDocuments.setBankTransactionRowNormalizer(bankTransactionRowNormalizer);
        analyzeDocuments.setBankTransactionTableHeaderIdentifier(headerIdentifier);
        analyzeDocuments.setBankTransactionTableFooterIdentifier(footerIdentifier);
        analyzeDocuments.setStatementBasicDetailExtractor(new StatementBasicDetailExtractor());
        analyzeDocuments.setBankSpecificParsingService(bankSpecific);

        DocumentAnalysisPipeline pipeline = new DocumentAnalysisPipeline();
        pipeline.setEPdfCharacterExtractionService(new EPdfCharacterExtractionService());
        pipeline.setBankSpecificParsingService(bankSpecific);
        pipeline.setAnalyzeDocuments(analyzeDocuments);

        NativeTableExtractionService nativeService = new NativeTableExtractionService(
                new NativePdfContentReader(),
                List.of(new BorderedGridTableExtractor(), new BoxGuidedTableExtractor(),
                        new TextAlignedRowSelectedTableExtractor()));
        NativeExtractionPolicyRegistry registry = new NativeExtractionPolicyRegistry();

        File root = new File(args[0]);
        File[] banks = root.listFiles(File::isDirectory);
        Arrays.sort(banks);
        int nativeOk = 0, fallback = 0, total = 0;
        for (File bank : banks) {
            String bankCode = bank.getName();
            List<NativeLayoutPolicy> policies = registry.policiesFor(bankCode);
            File[] pdfs = bank.listFiles((d, n) -> n.toLowerCase().endsWith(".pdf"));
            Arrays.sort(pdfs);
            for (File pdf : pdfs) {
                if (args.length > 1 && !pdf.getName().equals(args[1]) && !bankCode.equals(args[1])) continue;
                total++;
                String status;
                int txns = -1;
                try {
                    Optional<DocumentExtractionResult> nativeResult = nativeService.extract(pdf, policies);
                    if (nativeResult.isPresent()) {
                        DocumentExtractionRequest request = new DocumentExtractionRequest();
                        request.setStatementFile(pdf);
                        request.setBankName(bankCode);
                        DocumentExtractionResult result = pipeline.analyze(nativeResult.get(), request);
                        boolean confirmed = hasTransactionTable(result);
                        if (confirmed) {
                            txns = countTransactions(result);
                            status = "NATIVE(" + txns + " txns)";
                            nativeOk++;
                        } else {
                            status = "FALLBACK(no txn table confirmed)";
                            fallback++;
                        }
                    } else {
                        status = "FALLBACK(native extract empty)";
                        fallback++;
                    }
                } catch (Throwable t) {
                    status = "FALLBACK(error: " + t + ")";
                    fallback++;
                }
                System.out.printf("%-32s %-14s -> %s%n", bankCode, pdf.getName(), status);
            }
        }
        System.out.printf("%nTotal=%d nativeOk=%d fallbackToML=%d%n", total, nativeOk, fallback);
    }

    static boolean hasTransactionTable(DocumentExtractionResult result) {
        if (result == null || result.getPages() == null) return false;
        for (Page page : result.getPages().values()) {
            if (page.getTables() == null) continue;
            for (Table table : page.getTables().values()) {
                if (table.getIsTransactionTable() && table.getCells() != null && !table.getCells().isEmpty()) return true;
            }
        }
        return false;
    }

    static int countTransactions(DocumentExtractionResult result) {
        BankStatementVO vo = new BankStatementVO();
        vo.setDocumentExtractionResult(result);
        List<BankStatementVO> list = new ArrayList<>();
        list.add(vo);
        BankStatementProcessorImpl.extractTransactions(list);
        List<BankTransactionVO> txns = list.get(0).getBankTransactions();
        return txns == null ? 0 : txns.size();
    }

    static void setField(Object target, String name, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }
}

