import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.*;

import java.io.File;
import java.util.*;

public class DebugWords {
    public static void main(String[] args) throws Exception {
        NativePdfContentReader reader = new NativePdfContentReader();
        List<NativePdfPageContent> pages = reader.readPages(new File(args[0]));
        int pageNo = args.length > 1 ? Integer.parseInt(args[1]) : 1;
        NativePdfPageContent page = pages.get(pageNo - 1);
        List<NativeTextLine> lines = NativeTableSupport.buildTextLines(page.getWords());
        int shown = 0;
        for (NativeTextLine line : lines) {
            String content = line.content();
            boolean interesting = NativeTableSupport.containsDate(content) || NativeTableSupport.isTransactionHeaderLine(content);
            if (!interesting || shown > 8) continue;
            shown++;
            System.out.println("LINE y=" + line.getTop() + " :: " + content);
            for (Word w : line.getWords()) {
                System.out.printf("   [%s] x=%.3f..%.3f h=%.3f%n", w.getContent(), w.getX1(), w.getX3(), w.getHeight());
            }
        }
    }
}

import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.*;

import java.io.File;
import java.util.*;

public class DebugTable {
    public static void main(String[] args) throws Exception {
        NativePdfContentReader reader = new NativePdfContentReader();
        List<NativePdfPageContent> pages = reader.readPages(new File(args[0]));
        int pageNo = args.length > 1 ? Integer.parseInt(args[1]) : 1;
        String policy = args.length > 2 ? args[2] : "TEXT";
        NativeTableExtractor extractor = switch (policy) {
            case "GRID" -> new BorderedGridTableExtractor();
            case "BOX" -> new BoxGuidedTableExtractor();
            default -> new TextAlignedRowSelectedTableExtractor();
        };
        NativeExtractionContext ctx = new NativeExtractionContext();
        for (NativePdfPageContent page : pages) {
            List<Table> tables = extractor.extractTables(page, ctx);
            if (page.getPageNumber() != pageNo) continue;
            System.out.println("PAGE " + page.getPageNumber() + " tables=" + tables.size()
                    + " hRul=" + page.getHorizontalRulings().size() + " vRul=" + page.getVerticalRulings().size());
            for (Table t : tables) {
                System.out.println(" TABLE rows=" + t.getTotalRows() + " cols=" + t.getTotalColumns()
                        + " boundaries=" + t.getColumnBoundaries());
                int shown = 0;
                for (Map.Entry<Integer, Map<Integer, TableCell>> row : t.getCells().entrySet()) {
                    if (shown++ > 6) break;
                    StringBuilder sb = new StringBuilder("  row" + row.getKey() + (row.getValue().values().iterator().next().isHeaderOrFooterCell() ? "(H)" : "") + ": ");
                    for (Map.Entry<Integer, TableCell> c : row.getValue().entrySet()) {
                        sb.append("[").append(c.getValue().getContent()).append("] ");
