/**
 * Snaps the interior boundaries to the nearest whitespace band of the data below
 * the header: header labels are often not aligned with the data of their column
 * (e.g. right-aligned amounts), so the midpoint between two labels may cut
 * through data words. For every interior boundary the closest x-band that no
 * data word crosses is used instead.
 */
private void refineBoundariesWithData(List<Float> boundaries, List<NativeTextLine> dataLines) {
    List<float[]> spans = new ArrayList<>(); // {x1, x3} of every data word
    for (NativeTextLine line : dataLines) {
        for (Word word : line.getWords()) {
            spans.add(new float[]{word.getX1(), word.getX3()});
        }
    }
    if (spans.isEmpty()) {
        return;
    }
    for (int i = 1; i < boundaries.size() - 1; i++) {
        float boundary = boundaries.get(i);
        float windowLeft = boundary - BOUNDARY_SEARCH_WINDOW;
        float windowRight = boundary + BOUNDARY_SEARCH_WINDOW;

        // Collect the x positions of span edges inside the window as gap candidates
        List<Float> candidates = new ArrayList<>();
        candidates.add(boundary);
        for (float[] span : spans) {
            if (span[1] >= windowLeft && span[1] <= windowRight) {
                candidates.add(span[1] + MIN_GAP_HALF_WIDTH);
            }
            if (span[0] >= windowLeft && span[0] <= windowRight) {
                candidates.add(span[0] - MIN_GAP_HALF_WIDTH);
            }
        }
        Float best = null;
        float bestDistance = Float.MAX_VALUE;
        for (Float candidate : candidates) {
            if (candidate <= boundaries.get(i - 1) || candidate >= boundaries.get(i + 1)) {
                continue;
            }
            if (!crossesAnySpan(spans, candidate)) {
                float distance = Math.abs(candidate - boundary);
                if (distance < bestDistance) {
                    bestDistance = distance;
                    best = candidate;
                }
            }
        }
        if (best != null) {
            boundaries.set(i, best);
        }
    }
}

private boolean crossesAnySpan(List<float[]> spans, float x) {
    for (float[] span : spans) {
        if (span[0] < x - MIN_GAP_HALF_WIDTH && span[1] > x + MIN_GAP_HALF_WIDTH) {
            return true;
        }
    }
    return false;
}

