/**
 * Confirms a native result after the downstream analysis: a transaction table
 * must have been identified and the regular transaction extraction must recover
 * (nearly) all transaction-like rows of that table. Anything less falls back to
 * the ML path so the native migration can never silently lose transactions.
 */
private boolean nativeResultConfirmed(DocumentExtractionResult result) {
    if (!hasTransactionTable(result)) {
        return false;
    }
    try {
        BankStatementVO probe = new BankStatementVO();
        probe.setDocumentExtractionResult(result);
        List<BankStatementVO> probeList = new java.util.ArrayList<>();
        probeList.add(probe);
        BankStatementProcessorImpl.extractTransactions(probeList);
        int extracted = probe.getBankTransactions() != null ? probe.getBankTransactions().size() : 0;
        int candidates = countTransactionLikeRows(result);
        boolean confirmed = extracted >= MIN_CONFIRMED_TRANSACTIONS
                && extracted * 100 >= candidates * MIN_CONFIRMED_COVERAGE_PERCENT;
        if (!confirmed) {
            log.info("Native result yielded {} transactions out of {} transaction-like rows; not confirmed",
                    extracted, candidates);
        }
        return confirmed;
    } catch (Exception e) {
        log.warn("Failed to confirm native extraction result: {}", e.getMessage());
        return false;
    }
}

/**
 * Counts the non-header rows of the identified transaction tables that carry a
 * date-like and an amount-like token.
 */
private int countTransactionLikeRows(DocumentExtractionResult result) {
    int count = 0;
    for (Page page : result.getPages().values()) {
        if (page.getTables() == null) {
            continue;
        }
        for (Table table : page.getTables().values()) {
            if (!table.getIsTransactionTable() || table.getCells() == null) {
                continue;
            }
            for (Map<Integer, TableCell> row : table.getCells().values()) {
                boolean header = false;
                StringBuilder content = new StringBuilder();
                for (TableCell cell : row.values()) {
                    header |= cell.isHeaderOrFooterCell();
                    content.append(' ').append(cell.getContent());
                }
                if (!header
                        && NativeTableSupport.containsDate(content.toString())
                        && NativeTableSupport.containsAmount(content.toString())) {
                    count++;
                }
            }
        }
    }
    return count;
}

