/**
 * Splits columns whose header label groups were merged (e.g. "Balance" and
 * "Branch Name" printed close together) by looking for a persistent vertical
 * whitespace band inside the column with data on both sides on most lines.
 */
private void addPersistentGapSplits(List<Float> boundaries, List<NativeTextLine> dataLines) {
    boolean changed = true;
    int guard = 0;
    while (changed && guard++ < 4) {
        changed = false;
        for (int col = 0; col < boundaries.size() - 1; col++) {
            Float split = findPersistentGapSplit(boundaries.get(col), boundaries.get(col + 1), dataLines);
            if (split != null) {
                boundaries.add(col + 1, split);
                changed = true;
                break;
            }
        }
    }
}

private Float findPersistentGapSplit(float left, float right, List<NativeTextLine> dataLines) {
    if (right - left < 0.4f) {
        return null;
    }
    List<List<float[]>> lineSpans = new ArrayList<>();
    List<float[]> allSpans = new ArrayList<>();
    for (NativeTextLine line : dataLines) {
        List<float[]> spans = new ArrayList<>();
        for (Word word : line.getWords()) {
            float centerX = (word.getX1() + word.getX3()) / 2f;
            if (centerX > left && centerX < right) {
                float[] span = new float[]{word.getX1(), word.getX3()};
                spans.add(span);
                allSpans.add(span);
            }
        }
        if (!spans.isEmpty()) {
            lineSpans.add(spans);
        }
    }
    if (lineSpans.size() < 3) {
        return null;
    }

    List<Float> candidates = new ArrayList<>();
    for (float[] span : allSpans) {
        if (span[1] > left + 0.06f && span[1] < right - 0.06f) {
            candidates.add(span[1] + MIN_GAP_HALF_WIDTH);
        }
        if (span[0] > left + 0.06f && span[0] < right - 0.06f) {
            candidates.add(span[0] - MIN_GAP_HALF_WIDTH);
        }
    }

    Float best = null;
    float bestFraction = 0f;
    for (Float candidate : candidates) {
        if (crossesAnySpan(allSpans, candidate)) {
            continue;
        }
        int leftLines = 0;
        int rightLines = 0;
        for (List<float[]> spans : lineSpans) {
            boolean hasLeft = false;
            boolean hasRight = false;
            for (float[] span : spans) {
                float center = (span[0] + span[1]) / 2f;
                if (center < candidate) {
                    hasLeft = true;
                } else {
                    hasRight = true;
                }
            }
            if (hasLeft) {
                leftLines++;
            }
            if (hasRight) {
                rightLines++;
            }
        }
        float fraction = (float) Math.min(leftLines, rightLines) / lineSpans.size();
        if (fraction > bestFraction) {
            bestFraction = fraction;
            best = candidate;
        }
    }
    return bestFraction >= 0.6f ? best : null;
}

