import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.*;

import java.io.File;
import java.util.*;

public class DebugService {
    public static void main(String[] args) throws Exception {
        NativePdfContentReader reader = new NativePdfContentReader();
        List<NativePdfPageContent> pages = reader.readPages(new File(args[0]));
        String policy = args.length > 1 ? args[1] : "GRID";
        NativeTableExtractor extractor = switch (policy) {
            case "GRID" -> new BorderedGridTableExtractor();
            case "BOX" -> new BoxGuidedTableExtractor();
            default -> new TextAlignedRowSelectedTableExtractor();
        };
        NativeExtractionContext ctx = new NativeExtractionContext();
        for (NativePdfPageContent page : pages) {
            if (page.getPageNumber() > 6) break;
            List<Table> tables = extractor.extractTables(page, ctx);
            int rows = 0;
            for (Table t : tables) {
                for (Map<Integer, TableCell> row : t.getCells().values()) {
                    boolean header = false;
                    StringBuilder content = new StringBuilder();
                    for (TableCell cell : row.values()) {
                        header |= cell.isHeaderOrFooterCell();
                        content.append(' ').append(cell.getContent());
                    }
                    if (!header && NativeTableSupport.containsDate(content.toString())
                            && NativeTableSupport.containsAmount(content.toString())) rows++;
                }
            }
            int candidates = 0;
            List<String> candLines = new ArrayList<>();
            for (NativeTextLine line : NativeTableSupport.buildTextLines(page.getWords())) {
                String c = line.content();
                if (NativeTableSupport.containsDate(c) && NativeTableSupport.containsAmount(c)) { candidates++; candLines.add(c); }
            }
            System.out.println("page=" + page.getPageNumber() + " tables=" + tables.size() + " dataRows=" + rows + " candidates=" + candidates + " covOK=" + !(candidates >= 3 && rows < Math.max(1, candidates / 2)));
            if (candidates >= 3 && rows < Math.max(1, candidates / 2)) {
                for (String c : candLines.subList(0, Math.min(5, candLines.size()))) System.out.println("   CAND: " + c.substring(0, Math.min(120, c.length())));
            }
        }
    }
}

