public void fillPath(int windingRule) {
    for (float[] rect : pendingRectangles) {
        float width = rect[2] - rect[0];
        float height = rect[3] - rect[1];
        if (height <= FILLED_LINE_MAX_THICKNESS_POINTS && width > height) {
            // Thin filled rectangles are effectively drawn lines
            float y = (rect[1] + rect[3]) / 2f;
            commitSegment(rect[0], y, rect[2], y);
        } else if (width <= FILLED_LINE_MAX_THICKNESS_POINTS && height >= width) {
            float x = (rect[0] + rect[2]) / 2f;
            commitSegment(x, rect[1], x, rect[3]);
        } else if (width >= FILLED_CELL_MIN_SIZE_POINTS && height >= FILLED_CELL_MIN_SIZE_POINTS) {
            // Table cells drawn as filled boxes: their edges act as rulings
            commitSegment(rect[0], rect[1], rect[2], rect[1]);
            commitSegment(rect[0], rect[3], rect[2], rect[3]);
            commitSegment(rect[0], rect[1], rect[0], rect[3]);
            commitSegment(rect[2], rect[1], rect[2], rect[3]);
        }
    }
