/** Filled rectangles thinner than this (points) are treated as drawn lines. */
private static final float FILLED_LINE_MAX_THICKNESS_POINTS = 5.0f;
/** Filled rectangles with both dimensions above this (points) are treated as cell boxes. */
private static final float FILLED_CELL_MIN_SIZE_POINTS = 8.0f;

public static int findDateColumnIndex(List<Float> columnBoundaries,
                                      List<NativeTextLine> headerLines,
                                      List<NativeTextLine> dataLines) {
    int columnCount = columnBoundaries.size() - 1;
    // 1. By header label, verified against the data of the column (a "Value Date"
    // column whose words wrap mid-date must not become the anchor column)
    int firstLabelled = -1;
    for (int col = 0; col < columnCount; col++) {
        float left = columnBoundaries.get(col);
        float right = columnBoundaries.get(col + 1);
        for (NativeTextLine headerLine : headerLines) {
            String label = headerLine.contentBetween(left, right).toLowerCase(Locale.ROOT);
            if (label.contains("date")) {
                if (firstLabelled < 0) {
                    firstLabelled = col;
                }
                if (dataLines.isEmpty() || countDateLines(dataLines, left, right) >= 2) {
                    return col;
                }
            }
        }
    }
    // 2. By data content of the leading columns
    int bestColumn = -1;
    int bestCount = 0;
    for (int col = 0; col < Math.min(4, columnCount); col++) {
        float left = columnBoundaries.get(col);
        float right = columnBoundaries.get(col + 1);
        int count = countDateLines(dataLines, left, right);
        if (count > bestCount) {
            bestCount = count;
            bestColumn = col;
        }
    }
    if (bestCount >= 2) {
        return bestColumn;
    }
    return firstLabelled;
}

private static int countDateLines(List<NativeTextLine> lines, float left, float right) {
    int count = 0;
    for (NativeTextLine line : lines) {
        if (containsDate(line.contentBetween(left, right))) {
            count++;
        }
    }
    return count;
}

