@Override
public void fillPath(int windingRule) {
    for (float[] rect : pendingRectangles) {
        fillShape(rect[0], rect[1], rect[2], rect[3]);
    }
    if (pendingRectangles.isEmpty() && !pendingSegments.isEmpty()) {
        // Ruling lines and cell boxes may be drawn as filled polygon paths
        // instead of rectangle operators; use the path bounding box.
        float minX = Float.MAX_VALUE;
        float minY = Float.MAX_VALUE;
        float maxX = -Float.MAX_VALUE;
        float maxY = -Float.MAX_VALUE;
        for (float[] segment : pendingSegments) {
            minX = Math.min(minX, Math.min(segment[0], segment[2]));
            maxX = Math.max(maxX, Math.max(segment[0], segment[2]));
            minY = Math.min(minY, Math.min(segment[1], segment[3]));
            maxY = Math.max(maxY, Math.max(segment[1], segment[3]));
        }
        fillShape(minX, minY, maxX, maxY);
    }
    clearPending();
}

private void fillShape(float minX, float minY, float maxX, float maxY) {
    float width = maxX - minX;
    float height = maxY - minY;
    if (height <= FILLED_LINE_MAX_THICKNESS_POINTS && width > height) {
        // Thin filled shapes are effectively drawn lines
        float y = (minY + maxY) / 2f;
        commitSegment(minX, y, maxX, y);
    } else if (width <= FILLED_LINE_MAX_THICKNESS_POINTS && height >= width) {
        float x = (minX + maxX) / 2f;
        commitSegment(x, minY, x, maxY);
    } else if (width >= FILLED_CELL_MIN_SIZE_POINTS && height >= FILLED_CELL_MIN_SIZE_POINTS) {
        // Table cells drawn as filled boxes: their edges act as rulings
        commitSegment(minX, minY, maxX, minY);
        commitSegment(minX, maxY, maxX, maxY);
        commitSegment(minX, minY, minX, maxY);
        commitSegment(maxX, minY, maxX, maxY);
    }
}

