new = '''    @Override
    public List<Table> extractTables(NativePdfPageContent page, NativeExtractionContext context) {
        List<NativeTextLine> lines = NativeTableSupport.buildTextLines(page.getWords());
        if (lines.isEmpty()) {
            return List.of();
        }

        List<Integer> headerIndexes = findHeaderLineIndexes(lines);
        List<Table> tables = new LinkedList<>();

        // Lines before the first header continue the table of a previous page/segment
        int firstHeader = headerIndexes.isEmpty() ? lines.size() : headerIndexes.get(0);
        if (firstHeader > 0 && context.getLastColumnBoundaries() != null
                && context.getLastColumnBoundaries().size() - 1 >= MIN_COLUMNS
                && context.getLastDateColumnIndex() >= 0) {
            Table table = buildSegmentTable(page, List.of(), lines.subList(0, firstHeader),
                    context.getLastColumnBoundaries(), context.getLastDateColumnIndex(), context);
            if (table != null) {
                tables.add(table);
            }
        }

        for (int k = 0; k < headerIndexes.size(); k++) {
            int headerIndex = headerIndexes.get(k);
            List<NativeTextLine> headerLines = new LinkedList<>();
            headerLines.add(lines.get(headerIndex));
            // Two-line headers: absorb the next line when it is close and carries no data
            int next = headerIndex + 1;
            if (next < lines.size()
                    && !headerIndexes.contains(next)
                    && lines.get(next).getTop() - lines.get(headerIndex).getBottom() <= SECOND_HEADER_LINE_GAP
                    && !NativeTableSupport.containsDate(lines.get(next).content())
                    && !NativeTableSupport.containsAmount(lines.get(next).content())) {
                headerLines.add(lines.get(next));
            }
            int dataStartIndex = headerIndex + headerLines.size();
            int segmentEnd = k + 1 < headerIndexes.size() ? headerIndexes.get(k + 1) : lines.size();
            if (dataStartIndex >= segmentEnd) {
                continue;
            }
            List<NativeTextLine> segmentLines = lines.subList(dataStartIndex, segmentEnd);
            List<Float> boundaries = boundariesFromHeader(headerLines.get(0), segmentLines, page);
            if (boundaries == null || boundaries.size() - 1 < MIN_COLUMNS) {
                continue;
            }
            int dateColumn = NativeTableSupport.findDateColumnIndex(boundaries, headerLines, segmentLines);
            if (dateColumn < 0 || dateColumn >= boundaries.size() - 1) {
                continue;
            }
            Table table = buildSegmentTable(page, headerLines, segmentLines, boundaries, dateColumn, context);
            if (table != null) {
                tables.add(table);
            }
        }
        return tables;
    }

    /**
     * Builds a table from one page segment: optional header lines plus the data
     * lines below them, using the given column model.
     */
    private Table buildSegmentTable(NativePdfPageContent page, List<NativeTextLine> headerLines,
                                    List<NativeTextLine> segmentLines, List<Float> boundaries,
                                    int dateColumn, NativeExtractionContext context) {
        // Data lines: until an end-of-table marker
        List<NativeTextLine> dataLines = new LinkedList<>();
        for (NativeTextLine line : segmentLines) {
            if (isTableEndLine(line)) {
                break;
            }
            dataLines.add(line);
        }

        float dateLeft = boundaries.get(dateColumn);
        float dateRight = boundaries.get(dateColumn + 1);
        List<LogicalRow> dataRows = NativeTableSupport.groupLinesIntoRows(dataLines, dateLeft, dateRight, CONTINUATION_GAP);
        // Keep only rows that actually look like transactions (date + some amount)
        List<LogicalRow> rows = new LinkedList<>();
        if (!headerLines.isEmpty()) {
            LogicalRow header = LogicalRow.fromLine(headerLines.get(0), true);
            for (int i = 1; i < headerLines.size(); i++) {
                header.addLine(headerLines.get(i));
            }
            rows.add(header);
        }
        for (LogicalRow row : dataRows) {
            String content = rowContent(row);
            if (NativeTableSupport.containsAmount(content)) {
                rows.add(row);
            }
        }
        long transactionRows = rows.stream().filter(row -> !row.isHeader()).count();
        if (transactionRows < 1) {
            return null;
        }

        context.setLastColumnBoundaries(boundaries);
        context.setLastDateColumnIndex(dateColumn);
        return NativeTableSupport.buildTable(page.getPageNumber(), boundaries, rows);
    }

    /**
     * @return the indexes of all transaction-table header lines that have at least
     * one transaction-like line below them.
     */
    private List<Integer> findHeaderLineIndexes(List<NativeTextLine> lines) {
        List<Integer> indexes = new LinkedList<>();
        for (int i = 0; i < lines.size(); i++) {
            if (!NativeTableSupport.isTransactionHeaderLine(lines.get(i).content())) {
                continue;
            }
            boolean anchored = false;
            for (int j = i + 1; j < lines.size() && !anchored; j++) {
                String content = lines.get(j).content();
                if (NativeTableSupport.containsDate(content) && NativeTableSupport.containsAmount(content)) {
                    anchored = true;
                }
            }
            if (anchored) {
                indexes.add(i);
            }
        }
        return indexes;
    }

