private Float findPersistentGapSplit(float left, float right, List<NativeTextLine> dataLines) {
    if (right - left < 0.4f) {
        return null;
    }
    List<List<float[]>> lineSpans = new ArrayList<>();
    List<float[]> allSpans = new ArrayList<>();
    int dateLines = 0;
    for (NativeTextLine line : dataLines) {
        List<float[]> spans = new ArrayList<>();
        for (Word word : line.getWords()) {
            float centerX = (word.getX1() + word.getX3()) / 2f;
            if (centerX > left && centerX < right) {
                float[] span = new float[]{word.getX1(), word.getX3()};
                spans.add(span);
                allSpans.add(span);
            }
        }
        if (!spans.isEmpty()) {
            lineSpans.add(spans);
            if (NativeTableSupport.containsDate(line.contentBetween(left, right))) {
                dateLines++;
            }
        }
    }
    if (lineSpans.size() < 3) {
        return null;
    }
    // Date (and date-time) columns naturally consist of aligned word fragments;
    // they must not be split into artificial sub-columns.
    if (dateLines * 2 >= lineSpans.size()) {
        return null;
    }

    List<Float> candidates = new ArrayList<>();
    for (float[] span : allSpans) {
        if (span[1] > left + 0.06f && span[1] < right - 0.06f) {
            candidates.add(span[1] + MIN_GAP_HALF_WIDTH);
        }
        if (span[0] > left + 0.06f && span[0] < right - 0.06f) {
            candidates.add(span[0] - MIN_GAP_HALF_WIDTH);
        }
    }

    Float best = null;
    float bestFraction = 0f;
    for (Float candidate : candidates) {
        if (crossesAnySpan(allSpans, candidate)) {
            continue;
        }
        int leftLines = 0;
        int rightLines = 0;
        float leftMin = Float.MAX_VALUE;
        float leftMax = -Float.MAX_VALUE;
        float rightMin = Float.MAX_VALUE;
        float rightMax = -Float.MAX_VALUE;
        for (List<float[]> spans : lineSpans) {
            boolean hasLeft = false;
            boolean hasRight = false;
            for (float[] span : spans) {
                float center = (span[0] + span[1]) / 2f;
                if (center < candidate) {
                    hasLeft = true;
                    leftMin = Math.min(leftMin, span[0]);
                    leftMax = Math.max(leftMax, span[1]);
                } else {
                    hasRight = true;
                    rightMin = Math.min(rightMin, span[0]);
                    rightMax = Math.max(rightMax, span[1]);
                }
            }
            if (hasLeft) {
                leftLines++;
            }
            if (hasRight) {
                rightLines++;
            }
        }
        // Both resulting columns must have a reasonable data width of their own
        if (leftLines == 0 || rightLines == 0
                || leftMax - leftMin < MIN_SPLIT_COLUMN_WIDTH
                || rightMax - rightMin < MIN_SPLIT_COLUMN_WIDTH) {
            continue;
        }
        float fraction = (float) Math.min(leftLines, rightLines) / lineSpans.size();
        if (fraction > bestFraction) {
            bestFraction = fraction;
            best = candidate;
        }
    }
    return bestFraction >= 0.6f ? best : null;
}

