/**
 * @return true when the given x-range still carries a date on at least half of
 * the lines that have any content in it.
 */
private boolean sideKeepsDates(List<NativeTextLine> dataLines, float left, float right) {
    int linesWithContent = 0;
    int linesWithDate = 0;
    for (NativeTextLine line : dataLines) {
        String content = line.contentBetween(left, right);
        if (content.isBlank()) {
            continue;
        }
        linesWithContent++;
        if (NativeTableSupport.containsDate(content)) {
            linesWithDate++;
        }
    }
    return linesWithContent >= 3 && linesWithDate * 2 >= linesWithContent;
}

